async fn handle_content_list(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    params: ContentListParams,
) {
    let method = octos_core::ui_protocol::methods::CONTENT_LIST;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: SPA bridge listens for close-code 1008 to
        // trigger `crew:auth_expired` (clears token, routes to /login). The
        // RPC envelope alone leaves a stale-token client retrying forever.
        // Codex BLOCK (2026-05-13): close must precede the error envelope so
        // it survives backpressure when only one writer slot is free.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    // `ContentQuery` deserializes from the same JSON the REST query
    // string built. Forwarding the `filters` object lets clients opt
    // in to category / search / pagination without us redefining the
    // struct here. Null / empty filters fall back to the REST default
    // (`Default::default()`) so `content/list` with `{}` params works
    // identically to `GET /api/my/content` with no query string.
    let filters = if params.filters.is_null() {
        Value::Object(serde_json::Map::new())
    } else {
        params.filters
    };
    let query: crate::content_catalog::ContentQuery = match serde_json::from_value(filters) {
        Ok(q) => q,
        Err(err) => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::invalid_params(format!("{method}: invalid filters: {err}")),
            );
            return;
        }
    };
    let result = super::auth_handlers::my_content(
        State(state.clone()),
        headers.clone(),
        Extension(identity),
        axum::extract::Query(query),
    )
    .await;
    match result {
        Ok(axum::Json(value)) => match serde_json::to_value(&value) {
            Ok(json_value) => {
                let entries = json_value
                    .get("entries")
                    .cloned()
                    .unwrap_or_else(|| json!([]));
                let total = json_value.get("total").and_then(Value::as_u64).unwrap_or(0) as usize;
                send_aux_rpc_result(
                    ws,
                    id,
                    method,
                    json!({
                        "entries": entries,
                        "total": total,
                    }),
                );
            }
            Err(error) => {
                let _ = send_rpc_error(
                    ws,
                    Some(id),
                    RpcError::internal_error(format!(
                        "{method}: serialize content list failed: {error}"
                    )),
                );
            }
        },
        Err((status, message)) => {
            // `content/list` is a collection endpoint — no
            // addressable id. Use the generic resource context so a
            // (rare) 404 surfaces as `RESOURCE_NOT_FOUND` rather than
            // `UNKNOWN_SESSION`.
            let context = RestResourceContext::resource("content", "");
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, Some(message), &context),
            );
        }
    }
}

async fn handle_content_delete(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    params: ContentDeleteParams,
) {
    let method = octos_core::ui_protocol::methods::CONTENT_DELETE;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    let content_id = params.id.clone();
    let result = super::auth_handlers::delete_my_content(
        State(state.clone()),
        headers.clone(),
        Extension(identity),
        axum_path(params.id),
    )
    .await;
    match result {
        Ok(axum::Json(action)) => {
            send_aux_rpc_result(
                ws,
                id,
                method,
                json!({
                    "deleted": action.ok,
                }),
            );
        }
        Err((status, message)) => {
            // Content row miss → `RESOURCE_NOT_FOUND` with the content
            // id echoed in `data.identifier`. Previously this funnelled
            // through `UNKNOWN_SESSION` and stuffed the method name in
            // the `session_id` slot (codex review 2026-05-12).
            let context = RestResourceContext::resource("content", content_id);
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, Some(message), &context),
            );
        }
    }
}

async fn handle_content_bulk_delete(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    params: ContentBulkDeleteParams,
) {
    let method = octos_core::ui_protocol::methods::CONTENT_BULK_DELETE;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    // Codex review 2026-05-12: reject over-cap bulk-delete requests
    // before they reach the catalog write-lock. The 1 MiB frame limit
    // is a coarser secondary check; this per-method cap keeps a
    // single oversized request from monopolizing the catalog for
    // even a small bounded window. Mirrored in
    // `octos-core::ui_protocol::CONTENT_BULK_DELETE_MAX_IDS`.
    if params.ids.len() > octos_core::ui_protocol::CONTENT_BULK_DELETE_MAX_IDS {
        let _ = send_rpc_error(
            ws,
            Some(id),
            RpcError::invalid_params(format!(
                "{method}: ids count {} exceeds maximum of {}",
                params.ids.len(),
                octos_core::ui_protocol::CONTENT_BULK_DELETE_MAX_IDS,
            ))
            .with_data(json!({
                "max_ids": octos_core::ui_protocol::CONTENT_BULK_DELETE_MAX_IDS,
                "requested_ids": params.ids.len(),
            })),
        );
        return;
    }
    let result = super::auth_handlers::bulk_delete_my_content(
        State(state.clone()),
        headers.clone(),
        Extension(identity),
        axum::Json(super::auth_handlers::BulkDeleteRequest { ids: params.ids }),
    )
    .await;
    match result {
        Ok(axum::Json(action)) => {
            // The REST handler stuffs the count into the user-facing
            // message ("N item(s) deleted."). Parse it back out so the
            // WS shape can return a typed integer per the ADR.
            let deleted = action
                .message
                .as_deref()
                .and_then(|msg| msg.split_whitespace().next())
                .and_then(|first| first.parse::<usize>().ok())
                .unwrap_or(0);
            send_aux_rpc_result(ws, id, method, json!({ "deleted": deleted }));
        }
        Err((status, message)) => {
            // Bulk-delete is a collection operation; no single id is
            // the locus. Surface 404 (which the REST handler should
            // never return for this method) through the generic
            // resource context.
            let context = RestResourceContext::resource("content", "");
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, Some(message), &context),
            );
        }
    }
}

/// Per-field JSON-ESCAPED byte budgets for the memory RPC results
/// (codex #1621 r1 P1, tightened r2 P1). The REST panel intentionally
/// serves files up to `memory_panel::MAX_PANEL_FILE_BYTES` (2 MiB), but
/// an RPC result must fit ONE ~1 MiB WS text frame
/// (`MAX_TEXT_FRAME_BYTES`) — without a handler-level bound the
/// outbound framing guard (`preview_oversized_frame`) would splice a
/// head+tail preview into the largest string while the envelope still
/// reports success: silent corruption for a document viewer.
///
/// Budgets are measured in ESCAPED bytes (r2 P1: a flat raw-byte cap
/// under-counts — `serde_json` emits SIX bytes (`\u0001`) for a C0
/// control byte, so a control-heavy file capped by raw length would
/// still serialize past the frame and re-reach the silent preview).
/// `cap_index_by_escaped_len` walks the field with serde_json's actual
/// escaping table, so plain markdown keeps ~the full budget while
/// pathological content is cut exactly where its wire cost hits it.
/// Worst-case wire size is therefore the PLAIN SUM of the budgets:
///   96 (long_term) + 48 (today) + 7×24 (recent) + ~543 (entities —
///   bounded upstream at ≤ MAX_PANEL_ENTITIES=256 rows: summaries
///   ≤ 100 raw bytes (`octos_memory::extract_abstract`) → ≤ 600
///   escaped, names ≤ 255 raw → ≤ 1530 escaped (Unix filenames may
///   carry C0 controls at 6 wire bytes each), + per-row JSON
///   overhead) ≈ 855 KiB, under the frame cap with ~169 KiB margin.
/// Truncation is EXPLICIT: `<field>_truncated` + `<field>_total_bytes`
/// ride beside every capped field; the content itself is a clean UTF-8
/// prefix with NO in-band marker.
const MEMORY_RPC_LONG_TERM_BUDGET: usize = 96 * 1024;
const MEMORY_RPC_TODAY_BUDGET: usize = 48 * 1024;
const MEMORY_RPC_RECENT_NOTE_BUDGET: usize = 24 * 1024;
/// `memory/entity` is a single-document result — it gets the largest
/// budget that still clears the frame cap.
const MEMORY_RPC_ENTITY_CONTENT_BUDGET: usize = 384 * 1024;

/// Wire cost of one char in a JSON string per `serde_json`'s escaper:
/// `"` / `\` and the short control escapes (`\b \f \n \r \t`)
/// emit 2 bytes; every other C0 control emits 6 (`\u00XX`); everything
/// else passes through at its UTF-8 length.
fn json_escaped_len(c: char) -> usize {
    match c {
        '"' | '\\' | '\x08' | '\x0c' | '\n' | '\r' | '\t' => 2,
        c if (c as u32) < 0x20 => 6,
        c => c.len_utf8(),
    }
}

/// Largest raw prefix of `s` whose JSON-ESCAPED length fits
/// `escaped_budget`. Always a char boundary (walks `char_indices`).
fn cap_index_by_escaped_len(s: &str, escaped_budget: usize) -> usize {
    let mut used = 0usize;
    for (i, c) in s.char_indices() {
        let cost = json_escaped_len(c);
        if used + cost > escaped_budget {
            return i;
        }
        used += cost;
    }
    s.len()
}

/// Cap the string at `obj[field]` to `budget` ESCAPED bytes (UTF-8
/// boundary, clean prefix — no in-band marker) and record the truth
/// beside it as `<field>_truncated` + `<field>_total_bytes` (always
/// written, false/full-length when the field fit).
fn cap_memory_value_field(obj: &mut Value, field: &str, budget: usize) {
    let Some(Value::String(s)) = obj.get_mut(field) else {
        return;
    };
    let total = s.len();
    let cut = cap_index_by_escaped_len(s, budget);
    let truncated = cut < s.len();
    if truncated {
        s.truncate(cut);
    }
    if let Some(map) = obj.as_object_mut() {
        map.insert(format!("{field}_truncated"), json!(truncated));
        map.insert(format!("{field}_total_bytes"), json!(total));
    }
}

/// Apply the per-field budgets to a serialized `MemoryOverviewResponse`.
fn apply_memory_overview_budgets(overview: &mut Value) {
    cap_memory_value_field(overview, "long_term", MEMORY_RPC_LONG_TERM_BUDGET);
    cap_memory_value_field(overview, "today", MEMORY_RPC_TODAY_BUDGET);
    if let Some(recent) = overview.get_mut("recent").and_then(Value::as_array_mut) {
        for note in recent {
            cap_memory_value_field(note, "content", MEMORY_RPC_RECENT_NOTE_BUDGET);
        }
    }
}

async fn handle_memory_overview(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    _params: MemoryOverviewParams,
) {
    let method = octos_core::ui_protocol::methods::MEMORY_OVERVIEW;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    let result =
        super::memory_panel::my_memory(State(state.clone()), headers.clone(), Extension(identity))
            .await;
    match result {
        Ok(axum::Json(overview)) => match serde_json::to_value(&overview) {
            // The REST body is forwarded whole under `overview` (the
            // `system/status.get` wrap pattern) so the WS shape cannot
            // drift from `MemoryOverviewResponse` field by field — then
            // capped per document field so the result fits one WS frame
            // with EXPLICIT flags instead of the framing guard's silent
            // head+tail preview (codex #1621 r1 P1).
            Ok(mut value) => {
                apply_memory_overview_budgets(&mut value);
                send_aux_rpc_result(ws, id, method, json!({ "overview": value }))
            }
            Err(error) => {
                let _ = send_rpc_error(
                    ws,
                    Some(id),
                    RpcError::internal_error(format!(
                        "{method}: serialize memory overview failed: {error}"
                    )),
                );
            }
        },
        Err(status) => {
            // Collection-style endpoint — no addressable id. The REST
            // handler returns bare `StatusCode`s (no body), so there is
            // no detail string to forward.
            let context = RestResourceContext::resource("memory", "");
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, None, &context),
            );
        }
    }
}

async fn handle_memory_entity(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    params: MemoryEntityParams,
) {
    let method = octos_core::ui_protocol::methods::MEMORY_ENTITY;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    let entity_name = params.name.clone();
    let result = super::memory_panel::my_memory_entity(
        State(state.clone()),
        headers.clone(),
        Extension(identity),
        axum_path(params.name),
    )
    .await;
    match result {
        Ok(axum::Json(entity)) => {
            // `ok` is dropped — RPC success is carried by the envelope.
            // Content is capped with an EXPLICIT flag so an over-frame
            // page degrades to a declared prefix, never the framing
            // guard's silent in-band preview (codex #1621 r1 P1).
            let mut content = entity.content;
            let content_total_bytes = content.len();
            let cut = cap_index_by_escaped_len(&content, MEMORY_RPC_ENTITY_CONTENT_BUDGET);
            let content_truncated = cut < content.len();
            if content_truncated {
                content.truncate(cut);
            }
            send_aux_rpc_result(
                ws,
                id,
                method,
                json!({
                    "name": entity.name,
                    "content": content,
                    "content_truncated": content_truncated,
                    "content_total_bytes": content_total_bytes,
                }),
            );
        }
        Err(status) => {
            // Entity page miss → `RESOURCE_NOT_FOUND` with the page name
            // echoed in `data.identifier` (the REST 404 carries no body).
            let context = RestResourceContext::resource("memory_entity", entity_name);
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, None, &context),
            );
        }
    }
}

async fn handle_cron_list(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    _params: CronListParams,
) {
    let method = octos_core::ui_protocol::methods::CRON_LIST;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    let result =
        super::cron_panel::my_cron(State(state.clone()), headers.clone(), Extension(identity))
            .await;
    match result {
        Ok(axum::Json(body)) => {
            // The REST body is `{ ok, count, jobs, gateway_running }`;
            // `ok` is dropped (envelope carries success), the rest is
            // forwarded field-for-field per `CronListResult`.
            let jobs = body.get("jobs").cloned().unwrap_or_else(|| json!([]));
            let count = body.get("count").and_then(Value::as_u64).unwrap_or(0) as usize;
            let gateway_running = body
                .get("gateway_running")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            // Forward the truncation signal so a client can show "N of `count`"
            // instead of silently seeing a short list (`cron/list` bounds the
            // row set to keep the frame under budget).
            let truncated = body
                .get("truncated")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            send_aux_rpc_result(
                ws,
                id,
                method,
                json!({
                    "jobs": jobs,
                    "count": count,
                    "gateway_running": gateway_running,
                    "truncated": truncated,
                }),
            );
        }
        Err(status) => {
            // Collection-style endpoint — no addressable id, no REST body.
            let context = RestResourceContext::resource("cron", "");
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, None, &context),
            );
        }
    }
}

async fn handle_cron_toggle(
    ws: &WsConnection,
    state: &Arc<AppState>,
    headers: &HeaderMap,
    identity: Option<&AuthIdentity>,
    close_on_auth_unavailable: bool,
    id: String,
    params: CronToggleParams,
) {
    let method = octos_core::ui_protocol::methods::CRON_TOGGLE;
    let Some(identity) = identity.cloned() else {
        // Web PR #114 contract: see `close_ws_with_code` doc-comment. Codex
        // BLOCK (2026-05-13): close before error so it survives writer
        // backpressure when the channel has just one free slot.
        if close_on_auth_unavailable {
            let _ = close_ws_with_code(ws, 1008, "auth_expired");
        }
        let _ = send_rpc_error(ws, Some(id), auth_unavailable_error(method));
        return;
    };
    let job_id = params.job_id.clone();
    let result = super::cron_panel::set_my_cron_enabled(
        State(state.clone()),
        headers.clone(),
        Extension(identity),
        axum_path(params.job_id),
        axum::Json(super::cron_panel::ToggleBody {
            enabled: params.enabled,
        }),
    )
    .await;
    match result {
        Ok(axum::Json(body)) => {
            // REST success body is `{ ok: true, job }`; forward the job
            // (rendered exactly as a `cron/list` entry) per
            // `CronToggleResult`.
            let job = body.get("job").cloned().unwrap_or_else(|| json!(null));
            send_aux_rpc_result(ws, id, method, json!({ "job": job }));
        }
        Err((status, axum::Json(body))) => {
            // The REST error body is `{ ok: false, reason }`. Forward
            // `reason` as the error detail so clients can tell the
            // gateway-owns-the-store refusal (`detail:
            // "gateway_running"`, `rest_status: 409`) from a plain miss
            // without string-matching messages.
            let detail = body
                .get("reason")
                .and_then(Value::as_str)
                .map(str::to_owned)
                .unwrap_or_else(|| body.to_string());
            let context = RestResourceContext::resource("cron_job", job_id);
            let _ = send_rpc_error(
                ws,
                Some(id),
                rest_status_to_rpc_error(method, status, Some(detail), &context),
            );
        }
    }
}

fn task_query_store_or_error(
    state: &Arc<AppState>,
) -> Result<&crate::session_actor::SessionTaskQueryStore, RpcError> {
    state.task_query_store.as_ref().ok_or_else(|| {
        RpcError::runtime_not_ready("task supervisor not wired for AppUI task commands")
            .with_data(json!({ "kind": "runtime_unavailable" }))
    })
}

fn task_artifact_profile_id(
    session_id: &SessionKey,
    requested_profile_id: Option<&str>,
    connection_profile_id: Option<&str>,
) -> Result<String, RpcError> {
    Ok(
        validate_session_scope(session_id, requested_profile_id, connection_profile_id)?
            .or_else(|| session_id.profile_id().map(ToOwned::to_owned))
            .or_else(|| connection_profile_id.map(ToOwned::to_owned))
            .unwrap_or_else(|| MAIN_PROFILE_ID.to_owned()),
    )
}

fn task_artifact_list_result(
    state: &Arc<AppState>,
    orchestrator: &dyn AgentOrchestrator,
    connection_profile_id: Option<&str>,
    params: TaskArtifactListParams,
) -> Result<TaskArtifactListResult, RpcError> {
    let profile_id = task_artifact_profile_id(
        &params.session_id,
        params.profile_id.as_deref(),
        connection_profile_id,
    )?;
    let agent_id = resolve_task_artifact_agent_id(
        orchestrator,
        &params.session_id,
        &params.task_id,
        &profile_id,
        params.agent_id.as_deref(),
    )?;
    if let Some(agent_id) = agent_id {
        let result = orchestrator.list_agent_artifacts(AgentRequest {
            agent_id: agent_id.clone(),
            session_id: Some(params.session_id.clone()),
            profile_id,
        })?;
        let artifacts = result
            .get("artifacts")
            .and_then(Value::as_array)
            .map(|artifacts| {
                artifacts
                    .iter()
                    .map(task_artifact_record_from_value)
                    .collect()
            })
            .unwrap_or_default();
        return Ok(TaskArtifactListResult {
            session_id: params.session_id,
            task_id: params.task_id,
            agent_id: Some(agent_id),
            artifacts,
        });
    }

    let task = task_entry_for_session(state, &params.session_id, &params.task_id)?;
    Ok(TaskArtifactListResult {
        session_id: params.session_id,
        task_id: params.task_id,
        agent_id: None,
        artifacts: task_output_artifact_records(&task),
    })
}

fn task_artifact_read_result(
    state: &Arc<AppState>,
    orchestrator: &dyn AgentOrchestrator,
    connection_profile_id: Option<&str>,
    data_dir: Option<&Path>,
    params: TaskArtifactReadParams,
) -> Result<TaskArtifactReadResult, RpcError> {
    if params.artifact_id.is_none() && params.path.is_none() {
        return Err(
            RpcError::invalid_params("task/artifact/read requires artifact_id or path")
                .with_data(json!({ "kind": "task_artifact_selector_invalid" })),
        );
    }
    let profile_id = task_artifact_profile_id(
        &params.session_id,
        params.profile_id.as_deref(),
        connection_profile_id,
    )?;
    let agent_id = resolve_task_artifact_agent_id(
        orchestrator,
        &params.session_id,
        &params.task_id,
        &profile_id,
        params.agent_id.as_deref(),
    )?;
    if let Some(agent_id) = agent_id {
        let result = orchestrator.read_agent_artifact(AgentArtifactReadRequest {
            agent_id: agent_id.clone(),
            artifact_id: params.artifact_id.clone(),
            path: params.path.clone(),
            session_id: Some(params.session_id.clone()),
            profile_id,
        })?;
        let mut artifact = result
            .get("artifact")
            .map(task_artifact_record_from_value)
            .unwrap_or_else(|| task_artifact_record_for_selector(&params));
        if artifact.path.is_none() {
            artifact.path = params.path.clone();
        }
        let full_content = result
            .get("content")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .or_else(|| artifact.content.clone())
            .or_else(|| {
                artifact
                    .path
                    .as_deref()
                    .and_then(|path| read_task_artifact_text(path, data_dir))
            });
        let (content, cursor, next_cursor, has_more) =
            slice_task_artifact_content(full_content, params.cursor, params.limit_bytes);
        return Ok(TaskArtifactReadResult {
            session_id: params.session_id,
            task_id: params.task_id,
            agent_id: Some(agent_id),
            artifact,
            content,
            cursor,
            next_cursor,
            has_more,
        });
    }

    let task = task_entry_for_session(state, &params.session_id, &params.task_id)?;
    let artifacts = task_output_artifact_records(&task);
    let artifact = select_task_artifact(
        &artifacts,
        params.artifact_id.as_deref(),
        params.path.as_deref(),
    )?;
    let full_content = artifact
        .path
        .as_deref()
        .and_then(|path| read_task_artifact_text(path, data_dir));
    let (content, cursor, next_cursor, has_more) =
        slice_task_artifact_content(full_content, params.cursor, params.limit_bytes);
    Ok(TaskArtifactReadResult {
        session_id: params.session_id,
        task_id: params.task_id,
        agent_id: None,
        artifact,
        content,
        cursor,
        next_cursor,
        has_more,
    })
}

fn resolve_task_artifact_agent_id(
    orchestrator: &dyn AgentOrchestrator,
    session_id: &SessionKey,
    task_id: &TaskId,
    profile_id: &str,
    explicit_agent_id: Option<&str>,
) -> Result<Option<String>, RpcError> {
    if let Some(agent_id) = explicit_agent_id.filter(|agent_id| !agent_id.trim().is_empty()) {
        return Ok(Some(agent_id.to_owned()));
    }
    let result = orchestrator.list_agents(AgentListRequest {
        session_id: Some(session_id.clone()),
        profile_id: profile_id.to_owned(),
        connection_profile_id: None,
    })?;
    let task_id = task_id.to_string();
    Ok(result
        .get("agents")
        .and_then(Value::as_array)
        .and_then(|agents| {
            agents.iter().find_map(|agent| {
                let agent_id = agent.get("agent_id").and_then(Value::as_str)?;
                let matches_task = agent
                    .get("task_id")
                    .and_then(Value::as_str)
                    .is_some_and(|candidate| candidate == task_id)
                    || agent_id == task_id;
                matches_task.then(|| agent_id.to_owned())
            })
        }))
}

fn task_entry_for_session(
    state: &Arc<AppState>,
    session_id: &SessionKey,
    task_id: &TaskId,
) -> Result<TaskListEntry, RpcError> {
    task_list_snapshot(state, session_id)?
        .into_iter()
        .find(|task| &task.id == task_id)
        .ok_or_else(|| RpcError::unknown_task_id(task_id))
}

fn task_artifact_record_from_value(value: &Value) -> TaskArtifactRecord {
    let mut extra = BTreeMap::new();
    if let Some(object) = value.as_object() {
        for (key, value) in object {
            if !matches!(
                key.as_str(),
                "id" | "artifact_id" | "title" | "kind" | "status" | "path" | "content"
            ) {
                extra.insert(key.clone(), value.clone());
            }
        }
    }
    let id = value
        .get("id")
        .or_else(|| value.get("artifact_id"))
        .and_then(Value::as_str)
        .unwrap_or("artifact")
        .to_owned();
    let title = value
        .get("title")
        .and_then(Value::as_str)
        .unwrap_or(&id)
        .to_owned();
    TaskArtifactRecord {
        id,
        title,
        kind: value
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or("file")
            .to_owned(),
        status: value
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("ready")
            .to_owned(),
        path: value
            .get("path")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned),
        content: value
            .get("content")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned),
        extra,
    }
}

fn task_artifact_record_for_selector(params: &TaskArtifactReadParams) -> TaskArtifactRecord {
    let id = params
        .artifact_id
        .clone()
        .or_else(|| params.path.clone())
        .unwrap_or_else(|| "artifact".to_owned());
    TaskArtifactRecord {
        title: id.clone(),
        id,
        kind: "file".to_owned(),
        status: "ready".to_owned(),
        path: params.path.clone(),
        content: None,
        extra: BTreeMap::new(),
    }
}

fn task_output_artifact_records(task: &TaskListEntry) -> Vec<TaskArtifactRecord> {
    task.output_files
        .iter()
        .enumerate()
        .map(|(index, path)| {
            let title = Path::new(path)
                .file_name()
                .and_then(|name| name.to_str())
                .filter(|name| !name.is_empty())
                .unwrap_or(path)
                .to_owned();
            TaskArtifactRecord {
                id: format!("output-{:02}", index + 1),
                title,
                kind: task_artifact_kind_for_path(path),
                status: "ready".to_owned(),
                path: Some(path.clone()),
                content: None,
                extra: BTreeMap::new(),
            }
        })
        .collect()
}

fn task_artifact_kind_for_path(path: &str) -> String {
    match Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
    {
        Some("md" | "markdown") => "markdown",
        Some("json") => "json",
        Some("txt" | "log") => "text",
        Some("png" | "jpg" | "jpeg" | "gif" | "webp") => "image",
        _ => "file",
    }
    .to_owned()
}

fn select_task_artifact(
    artifacts: &[TaskArtifactRecord],
    artifact_id: Option<&str>,
    path: Option<&str>,
) -> Result<TaskArtifactRecord, RpcError> {
    artifacts
        .iter()
        .find(|artifact| {
            artifact_id.is_some_and(|id| id == artifact.id)
                || path.is_some_and(|path| artifact.path.as_deref() == Some(path))
        })
        .cloned()
        .ok_or_else(|| {
            let selector = artifact_id.or(path).unwrap_or("artifact");
            RpcError::not_found("task_artifact", selector)
                .with_data(json!({ "kind": "task_artifact_not_found", "artifact_id": selector }))
        })
}

fn read_task_artifact_text(path: &str, data_dir: Option<&Path>) -> Option<String> {
    let resolved = data_dir
        .and_then(|data_dir| {
            octos_bus::file_handle::resolve_scoped_file_handle(data_dir, path)
                .or_else(|| octos_bus::file_handle::resolve_legacy_file_request(data_dir, path))
        })
        .or_else(|| Path::new(path).is_absolute().then(|| PathBuf::from(path)))?;
    std::fs::read(resolved)
        .ok()
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
}

fn slice_task_artifact_content(
    content: Option<String>,
    cursor: Option<OutputCursor>,
    limit_bytes: Option<u64>,
) -> (
    Option<String>,
    Option<OutputCursor>,
    Option<OutputCursor>,
    bool,
) {
    let Some(content) = content else {
        return (None, None, None, false);
    };
    let len = content.len();
    let mut start = cursor
        .map(|cursor| cursor.offset as usize)
        .unwrap_or(0)
        .min(len);
    while start > 0 && !content.is_char_boundary(start) {
        start -= 1;
    }
    let limit = limit_bytes
        .and_then(|limit| usize::try_from(limit).ok())
        .filter(|limit| *limit > 0)
        .unwrap_or(64 * 1024);
    let mut end = start.saturating_add(limit).min(len);
    while end > start && !content.is_char_boundary(end) {
        end -= 1;
    }
    let text = content[start..end].to_owned();
    (
        Some(text),
        Some(OutputCursor {
            offset: start as u64,
        }),
        Some(OutputCursor { offset: end as u64 }),
        end < len,
    )
}

fn task_list_snapshot(
    state: &Arc<AppState>,
    session_id: &SessionKey,
) -> Result<Vec<TaskListEntry>, RpcError> {
    let store = task_query_store_or_error(state)?;
    match store.query_json(&session_id.to_string()) {
        Value::Array(tasks) => tasks
            .into_iter()
            .map(task_list_entry_from_value)
            .collect::<Result<Vec<_>, _>>(),
        _ => Err(RpcError::internal_error(
            "task supervisor query returned a non-array task snapshot",
        )),
    }
}

fn session_key_with_optional_topic(session_id: &SessionKey, topic: Option<&str>) -> SessionKey {
    let Some(topic) = topic.map(str::trim).filter(|topic| !topic.is_empty()) else {
        return session_id.clone();
    };
    SessionKey(format!("{}#{topic}", session_id.base_key()))
}

#[derive(serde::Deserialize)]
struct TaskListProjection {
    id: TaskId,
    #[serde(default)]
    tool_name: String,
    #[serde(default)]
    tool_call_id: String,
    #[serde(default)]
    parent_session_key: Option<SessionKey>,
    #[serde(default)]
    child_session_key: Option<SessionKey>,
    #[serde(default)]
    status: String,
    #[serde(default)]
    lifecycle_state: String,
    #[serde(default)]
    runtime_state: String,
    // #966 / M13-B — extended projection fields. Optional so legacy
    // snapshots from older TaskSupervisor query JSON deserialize cleanly.
    #[serde(default)]
    source: Option<String>,
    #[serde(default)]
    role: Option<String>,
    #[serde(default)]
    summary: Option<String>,
    #[serde(default)]
    artifact_count: Option<u32>,
    #[serde(default)]
    runtime_policy_stamp: Option<Value>,
    #[serde(default)]
    child_terminal_state: Option<String>,
    #[serde(default)]
    child_join_state: Option<String>,
    #[serde(default)]
    child_joined_at: Option<DateTime<Utc>>,
    #[serde(default)]
    child_failure_action: Option<String>,
    #[serde(default)]
    runtime_detail: Option<Value>,
    #[serde(default)]
    workflow_kind: Option<String>,
    #[serde(default)]
    current_phase: Option<String>,
    started_at: DateTime<Utc>,
    updated_at: DateTime<Utc>,
    #[serde(default)]
    completed_at: Option<DateTime<Utc>>,
    #[serde(default)]
    output_files: Vec<String>,
    #[serde(default)]
    error: Option<String>,
    #[serde(default)]
    session_key: Option<SessionKey>,
}

fn task_list_entry_from_value(value: Value) -> Result<TaskListEntry, RpcError> {
    let projected: TaskListProjection = serde_json::from_value(value)
        .map_err(|error| RpcError::internal_error(format!("invalid task snapshot: {error}")))?;
    let state = ui_task_state_from_label(&projected.lifecycle_state)
        .or_else(|| ui_task_state_from_label(&projected.runtime_state))
        .or_else(|| ui_task_state_from_label(&projected.status))
        .unwrap_or(UiTaskRuntimeState::Running);

    Ok(TaskListEntry {
        id: projected.id,
        tool_name: projected.tool_name,
        tool_call_id: projected.tool_call_id,
        state,
        status: projected.status,
        lifecycle_state: projected.lifecycle_state,
        runtime_state: projected.runtime_state,
        // #966 / M13-B — extended projection fields. Backed by
        // additional optional fields in the TaskSupervisor query
        // JSON; when absent (legacy snapshots), these stay None and
        // are omitted from the wire.
        source: projected.source,
        role: projected.role,
        summary: projected.summary,
        artifact_count: projected.artifact_count,
        runtime_policy_stamp: projected.runtime_policy_stamp,
        parent_session_key: projected.parent_session_key,
        child_session_key: projected.child_session_key,
        child_terminal_state: projected.child_terminal_state,
        child_join_state: projected.child_join_state,
        child_joined_at: projected.child_joined_at,
        child_failure_action: projected.child_failure_action,
        runtime_detail: projected.runtime_detail,
        workflow_kind: projected.workflow_kind,
        current_phase: projected.current_phase,
        started_at: projected.started_at,
        updated_at: projected.updated_at,
        completed_at: projected.completed_at,
        output_files: projected.output_files,
        error: projected.error,
        session_key: projected.session_key,
    })
}

fn ui_task_state_from_label(label: &str) -> Option<UiTaskRuntimeState> {
    match label {
        "pending" | "queued" | "spawned" => Some(UiTaskRuntimeState::Pending),
        "running" | "executing_tool" | "resolving_outputs" | "verifying_outputs"
        | "delivering_outputs" | "cleaning_up" | "verifying" => Some(UiTaskRuntimeState::Running),
        "completed" | "ready" => Some(UiTaskRuntimeState::Completed),
        "failed" => Some(UiTaskRuntimeState::Failed),
        "cancelled" | "canceled" => Some(UiTaskRuntimeState::Cancelled),
        _ => None,
    }
}

fn ensure_task_in_session(
    state: &Arc<AppState>,
    session_id: &SessionKey,
    task_id: &TaskId,
) -> Result<(), RpcError> {
    if task_list_snapshot(state, session_id)?
        .iter()
        .any(|task| &task.id == task_id)
    {
        Ok(())
    } else {
        Err(RpcError::unknown_task_id(task_id))
    }
}

fn task_cancel_rpc_error(task_id: &TaskId, error: octos_agent::TaskCancelError) -> RpcError {
    match error {
        octos_agent::TaskCancelError::NotFound => RpcError::unknown_task_id(task_id),
        octos_agent::TaskCancelError::AlreadyTerminal => {
            RpcError::invalid_params("task is already terminal")
                .with_data(json!({ "kind": "task_already_terminal" }))
        }
    }
}

/// Wave4-A: resolve the per-session `AdaptiveRouter` (if any) by routing
/// through the same `resolve_session_profile_runtime` path used by
/// `session/open` and `turn/start`. Returns `None` for sessions whose
/// profile has no router attached — single-provider config or
/// `adaptive_routing.enabled = false`.
fn resolve_router_for_session(
    state: &Arc<AppState>,
    session_id: &SessionKey,
    connection_profile_id: Option<&str>,
    routed_profile_id: Option<&str>,
) -> Result<Option<Arc<octos_llm::AdaptiveRouter>>, RpcError> {
    // Tenant-scope gate (P1). Without it the `session_id.profile_id()`-first
    // precedence below lets a tenant-B connection pass a `session_id` that
    // embeds tenant-A's profile and resolve — then `set_mode` mutate /
    // `get_metrics` read — tenant-A's `AdaptiveRouter`. Placing the check
    // inside the shared resolver protects BOTH router handlers by
    // construction.
    authorize_router_session_scope(session_id, connection_profile_id, routed_profile_id)?;
    let active_profile_id = session_id
        .profile_id()
        .map(ToOwned::to_owned)
        .or_else(|| routed_profile_id.map(ToOwned::to_owned));
    Ok(
        resolve_session_profile_runtime(state, active_profile_id.as_deref())
            .and_then(|profile_runtime| profile_runtime.adaptive_router.clone()),
    )
}

/// Tenant-scope gate for the router RPCs.
///
/// A hosted WS connection is authorized for its own authenticated
/// `connection_profile_id` AND — on a per-tenant subdomain — the
/// `routed_profile_id` that `is_authorized_for_profile` already cleared at
/// upgrade time (an admin / parent account operating a tenant it owns; a
/// forged `Host` for an unauthorized tenant 403s before this point, so a
/// present `routed_profile_id` is always trustworthy). A `session_id` whose
/// embedded profile is EITHER is in scope; a different tenant is rejected.
///
/// - An unscoped connection (`connection_profile_id == None` — bootstrap
///   admin token / local solo) is authorized for every profile.
/// - A bare (profile-less) `session_id` is authorized under the connection's
///   auth, matching `validate_authenticated_session_scope`'s `None` arm.
///
/// This is deliberately a touch more permissive than the bare
/// `validate_session_scope(session_id, None, connection_profile_id)` other
/// handlers use (it also honours `routed_profile_id`): a router RPC on a
/// hosted subdomain must not regress the authorized admin/parent access that
/// existed before this gate landed, while a genuine cross-tenant `session_id`
/// (matching neither authorized profile) is still rejected. `authenticated_
/// scope_mismatch_error` tags the rejection `auth_scope_violation` so the
/// handler emits the same 1008 close the other scope checks do.
fn authorize_router_session_scope(
    session_id: &SessionKey,
    connection_profile_id: Option<&str>,
    routed_profile_id: Option<&str>,
) -> Result<(), RpcError> {
    let Some(connection_profile_id) = connection_profile_id else {
        return Ok(());
    };
    let Some(session_profile) = session_id.profile_id() else {
        return Ok(());
    };
    if session_profile == connection_profile_id || routed_profile_id == Some(session_profile) {
        return Ok(());
    }
    Err(authenticated_scope_mismatch_error(
        "session_id is outside the authorized profile scope",
        connection_profile_id,
        Some(session_profile),
    ))
}

/// Wave4-A handler for `router/set_mode`. Parses `params.mode` into the
/// `AdaptiveMode` enum (lowercase string), dispatches to
/// `AdaptiveRouter::set_mode`, and returns a typed ack.
///
/// Returns `INVALID_PARAMS` for unknown modes and a typed
/// `runtime_unavailable` data tag when the session has no router (so
/// the client can disable its mode-switcher UI).
async fn handle_router_set_mode(
    ws: &WsConnection,
    state: &Arc<AppState>,
    connection_profile_id: Option<&str>,
    routed_profile_id: Option<&str>,
    id: String,
    params: octos_core::ui_protocol::RouterSetModeParams,
) {
    let method = octos_core::ui_protocol::methods::ROUTER_SET_MODE;
    let mode = match params.mode.as_str() {
        "off" => octos_llm::AdaptiveMode::Off,
        "hedge" => octos_llm::AdaptiveMode::Hedge,
        "lane" => octos_llm::AdaptiveMode::Lane,
        other => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::invalid_params(format!(
                    "{method}: unknown mode '{other}' (expected off | hedge | lane)"
                )),
            );
            return;
        }
    };
    let router = match resolve_router_for_session(
        state,
        &params.session_id,
        connection_profile_id,
        routed_profile_id,
    ) {
        Ok(Some(router)) => router,
        Ok(None) => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::invalid_params(format!(
                    "{method}: no adaptive router attached to this session"
                ))
                .with_data(json!({ "kind": "runtime_unavailable" })),
            );
            return;
        }
        // Cross-tenant session_id on a profile-scoped connection: reject
        // before touching another tenant's router.
        Err(error) => {
            send_scope_error(ws, id, error);
            return;
        }
    };
    router.set_mode(mode);
    let result = octos_core::ui_protocol::RouterSetModeResult { mode: params.mode };
    let value = match serde_json::to_value(&result) {
        Ok(v) => v,
        Err(error) => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::malformed_result(format!("{method}: serialize result: {error}")),
            );
            return;
        }
    };
    let _ = send_rpc_result(ws, id, value);
}

/// Wave4-A handler for `router/get_metrics`. Returns the same payload
/// shape as the `router/status` notification (lane scores, breaker
/// states, mode, current provider).
async fn handle_router_get_metrics(
    ws: &WsConnection,
    state: &Arc<AppState>,
    connection_profile_id: Option<&str>,
    routed_profile_id: Option<&str>,
    id: String,
    params: octos_core::ui_protocol::RouterGetMetricsParams,
) {
    let method = octos_core::ui_protocol::methods::ROUTER_GET_METRICS;
    let router = match resolve_router_for_session(
        state,
        &params.session_id,
        connection_profile_id,
        routed_profile_id,
    ) {
        Ok(Some(router)) => router,
        Ok(None) => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::invalid_params(format!(
                    "{method}: no adaptive router attached to this session"
                ))
                .with_data(json!({ "kind": "runtime_unavailable" })),
            );
            return;
        }
        // Cross-tenant session_id on a profile-scoped connection: reject
        // before reading another tenant's router metrics.
        Err(error) => {
            send_scope_error(ws, id, error);
            return;
        }
    };
    let status = router.adaptive_status();
    let result = octos_core::ui_protocol::RouterGetMetricsResult {
        provider_name: router.current_lane_key(),
        mode: status.mode.to_string(),
        qos_ranking: status.qos_ranking,
        lane_scores: router.lane_scores(),
        circuit_breakers: router.breaker_states(),
    };
    let value = match serde_json::to_value(&result) {
        Ok(v) => v,
        Err(error) => {
            let _ = send_rpc_error(
                ws,
                Some(id),
                RpcError::malformed_result(format!("{method}: serialize result: {error}")),
            );
            return;
        }
    };
    let _ = send_rpc_result(ws, id, value);
}

fn task_relaunch_rpc_error(task_id: &TaskId, error: octos_agent::TaskRelaunchError) -> RpcError {
    match error {
        octos_agent::TaskRelaunchError::NotFound => RpcError::unknown_task_id(task_id),
        octos_agent::TaskRelaunchError::StillActive => {
            RpcError::invalid_params("task is still active; cancel it before relaunching")
                .with_data(json!({ "kind": "task_still_active" }))
        }
    }
}

enum M9FixtureOutcome {
    Completed,
    Errored { code: &'static str, message: String },
    Interrupted,
}

async fn m9_fixture_delay_or_interrupt(
    interrupt_rx: &mut mpsc::Receiver<()>,
    duration: std::time::Duration,
) -> bool {
    tokio::select! {
        _ = interrupt_rx.recv() => true,
        _ = tokio::time::sleep(duration) => false,
    }
}

fn m9_fixture_has_pending_interrupt(interrupt_rx: &mut mpsc::Receiver<()>) -> bool {
    matches!(interrupt_rx.try_recv(), Ok(_))
}

async fn run_m9_fixture_turn(
    ws: WsConnection,
    state: Arc<AppState>,
    ledger: Arc<UiProtocolLedger>,
    contracts: Arc<UiProtocolContractStores>,
    params: TurnStartParams,
    fixture: M9ProtocolFixture,
    turn_state: Arc<TokioMutex<TurnState>>,
    mut interrupt_rx: mpsc::Receiver<()>,
) {
    let session_id = params.session_id.clone();
    let turn_id = params.turn_id.clone();
    let started = UiNotification::TurnStarted(octos_core::ui_protocol::TurnStartedEvent {
        session_id: session_id.clone(),
        turn_id: turn_id.clone(),
        timestamp: Utc::now(),
        // UPCR-2026-014 (M9-α-9): WS turn-start path has no topic in
        // scope today; the SSE bridge in α-9 plumbs topic separately.
        topic: None,
    });
    if send_notification_lifecycle(&ws, &ledger, started).is_err() {
        let _ = transition_to_terminal(&turn_state, TerminalReason::Errored).await;
        contracts.scopes.evict_turn(&session_id, &turn_id);
        return;
    }
    let _ = send_notification_durable(
        &ws,
        &ledger,
        UiNotification::ProgressUpdated(UiProgressEvent::new(
            session_id.clone(),
            Some(turn_id.clone()),
            UiProgressMetadata::new(progress_kinds::STATUS).with_message("fixture turn running"),
        )),
    );

    let outcome = match fixture {
        M9ProtocolFixture::Basic => {
            let _ = send_notification_ephemeral(
                &ws,
                &ledger,
                UiNotification::MessageDelta(MessageDeltaEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    text: "OK".to_owned(),
                }),
            );
            if m9_fixture_delay_or_interrupt(
                &mut interrupt_rx,
                std::time::Duration::from_millis(20),
            )
            .await
            {
                M9FixtureOutcome::Interrupted
            } else {
                M9FixtureOutcome::Completed
            }
        }
        M9ProtocolFixture::M19StdioHappyPath => {
            let _ = send_notification_ephemeral(
                &ws,
                &ledger,
                UiNotification::MessageDelta(MessageDeltaEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    text: "`M19_STDIO_HAPPY_PATH_FINAL_LINE`".to_owned(),
                }),
            );
            if m9_fixture_delay_or_interrupt(
                &mut interrupt_rx,
                std::time::Duration::from_millis(20),
            )
            .await
            {
                M9FixtureOutcome::Interrupted
            } else {
                M9FixtureOutcome::Completed
            }
        }
        M9ProtocolFixture::Slow => {
            let mut interrupted = false;
            for _ in 0..80 {
                if m9_fixture_has_pending_interrupt(&mut interrupt_rx) {
                    interrupted = true;
                    break;
                }
                let _ = send_notification_ephemeral(
                    &ws,
                    &ledger,
                    UiNotification::MessageDelta(MessageDeltaEvent {
                        session_id: session_id.clone(),
                        topic: None,
                        turn_id: turn_id.clone(),
                        text: "OK\n".to_owned(),
                    }),
                );
                if m9_fixture_delay_or_interrupt(
                    &mut interrupt_rx,
                    std::time::Duration::from_millis(25),
                )
                .await
                {
                    interrupted = true;
                    break;
                }
            }
            if interrupted {
                M9FixtureOutcome::Interrupted
            } else {
                M9FixtureOutcome::Completed
            }
        }
        M9ProtocolFixture::ToolEvents => {
            let tool_call_id = format!("m9-tool-{}", turn_id.0);
            let topic = session_id.topic().map(ToOwned::to_owned);
            let _ = send_notification_durable(
                &ws,
                &ledger,
                UiNotification::ToolStarted(ToolStartedEvent {
                    session_id: session_id.clone(),
                    topic: topic.clone(),
                    turn_id: turn_id.clone(),
                    tool_call_id: tool_call_id.clone(),
                    tool_name: "list_dir".to_owned(),
                    arguments: Some(json!({ "path": "." })),
                }),
            );
            let _ = send_notification_durable(
                &ws,
                &ledger,
                UiNotification::ToolProgress(ToolProgressEvent {
                    session_id: session_id.clone(),
                    topic: topic.clone(),
                    turn_id: turn_id.clone(),
                    tool_call_id: tool_call_id.clone(),
                    message: Some("listing workspace".to_owned()),
                    progress_pct: Some(50.0),
                }),
            );
            let _ = send_notification_durable(
                &ws,
                &ledger,
                UiNotification::ToolCompleted(ToolCompletedEvent {
                    session_id: session_id.clone(),
                    topic,
                    turn_id: turn_id.clone(),
                    tool_call_id,
                    tool_name: "list_dir".to_owned(),
                    success: Some(true),
                    output_preview: Some("deterministic fixture listing".to_owned()),
                    duration_ms: Some(1),
                }),
            );
            if m9_fixture_delay_or_interrupt(
                &mut interrupt_rx,
                std::time::Duration::from_millis(20),
            )
            .await
            {
                M9FixtureOutcome::Interrupted
            } else {
                M9FixtureOutcome::Completed
            }
        }
        M9ProtocolFixture::Approval => {
            let approval_id = ApprovalId::new();
            let mut request = ApprovalRequestedEvent::generic(
                session_id.clone(),
                approval_id.clone(),
                turn_id.clone(),
                "shell",
                "M9 approval fixture",
                "printf m9-approval-e2e",
            );
            request.approval_kind = Some(approval_kinds::COMMAND.to_owned());
            request.risk = Some("low".to_owned());
            request.typed_details = Some(ApprovalTypedDetails::command(
                ApprovalCommandDetails {
                    argv: vec!["printf".to_owned(), "m9-approval-e2e".to_owned()],
                    command_line: Some("printf m9-approval-e2e".to_owned()),
                    cwd: None,
                    env_keys: Vec::new(),
                    tool_call_id: Some(format!("m9-approval-{}", turn_id.0)),
                },
                None,
            ));
            let response_rx = contracts.approvals.request_runtime(request.clone());
            if let Err(error) =
                send_notification_durable(&ws, &ledger, UiNotification::ApprovalRequested(request))
            {
                cancel_approval_after_request_send_failure(
                    contracts.as_ref(),
                    &ws,
                    &ledger,
                    &session_id,
                    &approval_id,
                    &turn_id,
                );
                M9FixtureOutcome::Errored {
                    code: "approval_send_failed",
                    message: format!("approval/requested notification not delivered: {error:?}"),
                }
            } else {
                tokio::select! {
                    _ = interrupt_rx.recv() => M9FixtureOutcome::Interrupted,
                    decision = response_rx => {
                        let text = match decision.unwrap_or(ApprovalDecision::Deny) {
                            ApprovalDecision::Approve => "approval approved",
                            ApprovalDecision::Deny | ApprovalDecision::Unknown(_) => "approval denied",
                        };
                        let _ = send_notification_ephemeral(
                            &ws,
                            &ledger,
                            UiNotification::MessageDelta(MessageDeltaEvent {
                                session_id: session_id.clone(),
                                topic: None,
                                turn_id: turn_id.clone(),
                                text: text.to_owned(),
                            }),
                        );
                        M9FixtureOutcome::Completed
                    }
                }
            }
        }
        M9ProtocolFixture::ReplayLossy | M9ProtocolFixture::ReplayLossyForcedTerminalDrop => {
            ws.metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
            emit_replay_lossy_opportunistic(&ws, &ledger, &session_id.0);
            let delay = if matches!(fixture, M9ProtocolFixture::ReplayLossyForcedTerminalDrop) {
                std::time::Duration::from_millis(250)
            } else {
                std::time::Duration::from_millis(20)
            };
            if m9_fixture_delay_or_interrupt(&mut interrupt_rx, delay).await {
                M9FixtureOutcome::Interrupted
            } else {
                M9FixtureOutcome::Completed
            }
        }
        M9ProtocolFixture::TaskOutput => {
            match seed_m9_task_output_fixture(
                state.as_ref(),
                &session_id,
                ws.clone(),
                Arc::clone(&ledger),
            )
            .await
            {
                Ok(task_id) => {
                    let _ = send_notification_durable(
                        &ws,
                        &ledger,
                        UiNotification::TaskUpdated(TaskUpdatedEvent {
                            session_id: session_id.clone(),
                            topic: None,
                            task_id: task_id.clone(),
                            title: "M9 task output fixture".to_owned(),
                            state: UiTaskRuntimeState::Running,
                            tool_call_id: None,
                            runtime_detail: Some(
                                "persisted deterministic task snapshot".to_owned(),
                            ),
                            // #1123 / M13-B — synthetic fixture path has no
                            // BackgroundTask projection; leave all five fields
                            // unset so the wire shape stays bare.
                            source: None,
                            role: None,
                            summary: None,
                            artifact_count: None,
                            runtime_policy_stamp: None,
                            // C1 step 4: stamp the originating turn.
                            turn_id: Some(turn_id.clone()),
                        }),
                    );
                    let _ = send_notification_durable(
                        &ws,
                        &ledger,
                        UiNotification::TaskOutputDelta(TaskOutputDeltaEvent {
                            session_id: session_id.clone(),
                            topic: None,
                            task_id: task_id.clone(),
                            cursor: OutputCursor { offset: 0 },
                            text: "fixture output line one\nfixture output line two\n".to_owned(),
                        }),
                    );
                    let _ = send_notification_durable(
                        &ws,
                        &ledger,
                        UiNotification::TaskUpdated(TaskUpdatedEvent {
                            session_id: session_id.clone(),
                            topic: None,
                            task_id,
                            title: "M9 task output fixture".to_owned(),
                            state: UiTaskRuntimeState::Completed,
                            tool_call_id: None,
                            runtime_detail: Some("fixture complete".to_owned()),
                            source: None,
                            role: None,
                            summary: None,
                            artifact_count: None,
                            runtime_policy_stamp: None,
                            // C1 step 4: stamp the originating turn.
                            turn_id: Some(turn_id.clone()),
                        }),
                    );
                    if m9_fixture_delay_or_interrupt(
                        &mut interrupt_rx,
                        std::time::Duration::from_millis(20),
                    )
                    .await
                    {
                        M9FixtureOutcome::Interrupted
                    } else {
                        M9FixtureOutcome::Completed
                    }
                }
                Err(message) => M9FixtureOutcome::Errored {
                    code: "task_fixture_failed",
                    message,
                },
            }
        }
        M9ProtocolFixture::M14CodexP0ToolParity => {
            run_m14_codex_p0_tool_parity_fixture_turn(
                &ws,
                &ledger,
                state.as_ref(),
                &session_id,
                &turn_id,
                &mut interrupt_rx,
            )
            .await
        }
        M9ProtocolFixture::M15LiveSubagents => {
            run_m15_live_subagent_fixture_turn(
                &ws,
                &ledger,
                &session_id,
                &turn_id,
                &mut interrupt_rx,
            )
            .await
        }
    };

    match outcome {
        M9FixtureOutcome::Completed => {
            if matches!(fixture, M9ProtocolFixture::ReplayLossyForcedTerminalDrop) {
                try_emit_completed_terminal_with_forced_backpressure(
                    &turn_state,
                    &ws,
                    &ledger,
                    &session_id,
                    &turn_id,
                )
                .await;
            } else {
                try_emit_terminal(
                    &turn_state,
                    TerminalReason::Completed,
                    &ws,
                    &ledger,
                    &session_id,
                    &turn_id,
                    None,
                    // M9 fixtures replay canned events; no live LLM token data.
                    None,
                )
                .await;
            }
        }
        M9FixtureOutcome::Errored { code, message } => {
            try_emit_terminal(
                &turn_state,
                TerminalReason::Errored,
                &ws,
                &ledger,
                &session_id,
                &turn_id,
                Some((code, message.as_str())),
                None,
            )
            .await;
        }
        M9FixtureOutcome::Interrupted => {
            let cancelled = contracts.approvals.cancel_pending_for_turn(
                &session_id,
                &turn_id,
                approval_cancelled_reasons::TURN_INTERRUPTED,
            );
            for entry in cancelled {
                let _ = send_notification_durable(
                    &ws,
                    &ledger,
                    UiNotification::ApprovalCancelled(ApprovalCancelledEvent::turn_interrupted(
                        session_id.clone(),
                        entry.approval_id,
                        entry.turn_id,
                    )),
                );
            }
            try_emit_terminal(
                &turn_state,
                TerminalReason::Interrupted,
                &ws,
                &ledger,
                &session_id,
                &turn_id,
                Some(("interrupted", "turn interrupted by client")),
                None,
            )
            .await;
        }
    }

    contracts.scopes.evict_turn(&session_id, &turn_id);
}

struct M14CodexP0SoakSpawnTool;

#[async_trait::async_trait]
impl octos_agent::tools::Tool for M14CodexP0SoakSpawnTool {
    fn name(&self) -> &str {
        "spawn"
    }

    fn description(&self) -> &str {
        "Deterministic native spawn delegate for the #969 Codex P0 tool parity soak."
    }

    fn tags(&self) -> &[&str] {
        &["gateway", "code"]
    }

    fn input_schema(&self) -> Value {
        json!({"type": "object", "additionalProperties": true})
    }

    async fn execute(&self, args: &Value) -> eyre::Result<octos_agent::ToolResult> {
        self.execute_with_context(&octos_agent::tools::ToolContext::zero(), args)
            .await
    }

    async fn execute_with_context(
        &self,
        ctx: &octos_agent::tools::ToolContext,
        args: &Value,
    ) -> eyre::Result<octos_agent::ToolResult> {
        let Some(supervisor) = ctx.task_supervisor.as_ref() else {
            return Ok(octos_agent::ToolResult {
                output: "spawn delegate requires a task supervisor".to_owned(),
                success: false,
                ..Default::default()
            });
        };
        let tool_call_id = format!("m14-codex-p0-spawn-{}", Utc::now().timestamp_millis());
        let task_id = supervisor.register_with_input(
            "spawn",
            &tool_call_id,
            ctx.parent_session_key.as_deref(),
            Some(args.clone()),
        );
        supervisor.mark_running(&task_id);

        if let Some(path) = args
            .get("context")
            .and_then(|context| context.get("artifact_path"))
            .and_then(Value::as_str)
            .filter(|path| !path.trim().is_empty())
        {
            let artifact_path = PathBuf::from(path);
            if let Some(parent) = artifact_path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            let _ = std::fs::write(
                &artifact_path,
                format!(
                    "# #969 Codex P0 Soak Reviewer\n\nTask `{task_id}` accepted by deterministic native spawn delegate.\n"
                ),
            );
        }

        append_appui_evidence_jsonl(
            "task-ledger.jsonl",
            json!({
                "event": "agent_started",
                "issue": 969,
                "agent_id": task_id,
                "tool_call_id": tool_call_id,
                "backend_kind": "m14_codex_p0_soak_spawn",
            }),
        );

        Ok(octos_agent::ToolResult {
            output: json!({
                "task_id": task_id,
                "status": "running",
                "backend": "m14_codex_p0_soak_spawn",
                "task": args.get("task"),
            })
            .to_string(),
            success: true,
            structured_metadata: Some(json!({
                "codex_soak": "m14_codex_p0_tool_parity",
                "native_tool": "spawn",
                "agent_id": task_id,
            })),
            ..Default::default()
        })
    }
}

fn m14_codex_tool_preview(output: &str) -> String {
    let mut preview: String = output.chars().take(512).collect();
    if output.chars().count() > 512 {
        preview.push_str("...");
    }
    preview
}

struct M14CodexToolCallEnv<'a> {
    ws: &'a WsConnection,
    ledger: &'a UiProtocolLedger,
    registry: &'a octos_agent::ToolRegistry,
    ctx: &'a octos_agent::tools::ToolContext,
    session_id: &'a SessionKey,
    turn_id: &'a TurnId,
}

async fn m14_codex_tool_call(
    env: &M14CodexToolCallEnv<'_>,
    index: usize,
    tool_name: &str,
    args: Value,
    expected_success: bool,
) -> Result<octos_agent::ToolResult, String> {
    let tool_call_id = format!("m14-codex-p0-{index}-{tool_name}-{}", env.turn_id.0);
    let topic = env.session_id.topic().map(ToOwned::to_owned);
    let _ = send_notification_durable(
        env.ws,
        env.ledger,
        UiNotification::ToolStarted(ToolStartedEvent {
            session_id: env.session_id.clone(),
            topic: topic.clone(),
            turn_id: env.turn_id.clone(),
            tool_call_id: tool_call_id.clone(),
            tool_name: tool_name.to_owned(),
            arguments: Some(args.clone()),
        }),
    );
    let result = env
        .registry
        .execute_with_context(env.ctx, tool_name, &args)
        .await
        .map_err(|error| format!("{tool_name} execution failed: {error}"))?;
    let metadata = result.structured_metadata.clone();
    let output_preview = m14_codex_tool_preview(&result.output);
    let success = result.success;
    let _ = send_notification_durable(
        env.ws,
        env.ledger,
        UiNotification::ToolCompleted(ToolCompletedEvent {
            session_id: env.session_id.clone(),
            topic,
            turn_id: env.turn_id.clone(),
            tool_call_id: tool_call_id.clone(),
            tool_name: tool_name.to_owned(),
            success: Some(success),
            output_preview: Some(output_preview.clone()),
            duration_ms: Some(1),
        }),
    );
    append_appui_evidence_jsonl(
        "task-ledger.jsonl",
        json!({
            "event": "tool_completed",
            "issue": 969,
            "session_id": env.session_id,
            "turn_id": env.turn_id,
            "tool_call_id": tool_call_id,
            "tool_name": tool_name,
            "success": success,
            "expected_success": expected_success,
            "output_preview": output_preview,
            "metadata": metadata,
        }),
    );
    if success != expected_success {
        return Err(format!(
            "{tool_name} success mismatch: expected {expected_success}, got {success}"
        ));
    }
    Ok(result)
}

fn m14_codex_parse_json_output(tool_name: &str, output: &str) -> Result<Value, String> {
    serde_json::from_str(output)
        .map_err(|error| format!("{tool_name} output was not JSON: {error}; output={output}"))
}

async fn run_m14_codex_p0_tool_parity_fixture_turn(
    ws: &WsConnection,
    ledger: &UiProtocolLedger,
    _state: &AppState,
    session_id: &SessionKey,
    turn_id: &TurnId,
    interrupt_rx: &mut mpsc::Receiver<()>,
) -> M9FixtureOutcome {
    append_appui_server_log("#969 Codex P0 tool parity soak started");
    let workspace = session_workspaces()
        .get(session_id)
        .or_else(|| appui_evidence_dir().map(|dir| dir.join("workspace")))
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
    if let Err(error) = std::fs::create_dir_all(&workspace) {
        return M9FixtureOutcome::Errored {
            code: "codex_p0_workspace_failed",
            message: format!("failed to create #969 soak workspace: {error}"),
        };
    }
    let evidence_dir = appui_evidence_dir().unwrap_or_else(|| workspace.join(".octos-969"));
    let artifact_dir = evidence_dir.join("agent-artifacts");
    if let Err(error) = std::fs::create_dir_all(&artifact_dir) {
        return M9FixtureOutcome::Errored {
            code: "codex_p0_artifact_dir_failed",
            message: format!("failed to create #969 soak artifact directory: {error}"),
        };
    }

    let mut registry = octos_agent::ToolRegistry::with_builtins(&workspace);
    registry.register(M14CodexP0SoakSpawnTool);
    let supervisor = registry.supervisor();
    let mut ctx = octos_agent::tools::ToolContext::zero();
    ctx.task_supervisor = Some(supervisor.clone());
    ctx.parent_session_key = Some(session_id.to_string());
    let call_env = M14CodexToolCallEnv {
        ws,
        ledger,
        registry: &registry,
        ctx: &ctx,
        session_id,
        turn_id,
    };
    let tool_names = model_visible_tool_names(Some(&registry));
    let tool_name_refs: Vec<&str> = tool_names.iter().map(String::as_str).collect();

    write_appui_evidence_json(
        "tool-registry-snapshot.json",
        json!({
            "scenario": "m14_codex_p0_tool_parity",
            "issue": 969,
            "workspace": workspace.to_string_lossy(),
            "tools": tool_names.clone(),
        }),
    );
    write_appui_evidence_json(
        "tool-contract.json",
        super::coding_tool_contract::tool_status_list_payload(
            super::coding_tool_contract::ToolStatusListContext {
                profile_id: session_id.profile_id(),
                session_id: &session_id.to_string(),
                policy: super::coding_tool_contract::ToolPolicyView::default(),
                available_model_tools: &tool_name_refs,
                disabled_model_tools: &[],
                deferred_model_tools: &[],
                include_coding_tool_contract: true,
            },
        ),
    );
    let _ = std::fs::write(
        evidence_dir.join("tui-capture.txt"),
        "#969 Codex P0 tool parity soak ran through AppUI WS and stdio fixtures.\n",
    );

    let mut step = 0;
    macro_rules! next_step {
        () => {{
            step += 1;
            step
        }};
    }

    let run = async {
        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "update_plan",
            json!({
                "explanation": "#969 P0 parity soak",
                "plan": [
                    {"step": "exercise canonical tools", "status": "in_progress"},
                    {"step": "record evidence", "status": "pending"}
                ]
            }),
            true,
        )
        .await?;

        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "request_user_input",
            json!({
                "questions": [{
                    "header": "Parity",
                    "id": "continue_soak",
                    "question": "Continue the #969 Codex P0 parity soak?",
                    "options": [
                        {"label": "Continue (Recommended)", "description": "Record the host prompt request."},
                        {"label": "Stop", "description": "Exercise the alternate option shape."}
                    ]
                }]
            }),
            true,
        )
        .await?;
        append_appui_evidence_jsonl(
            "approval-events.jsonl",
            json!({
                "event": "user_input_requested",
                "issue": 969,
                "tool_name": "request_user_input",
                "status": "requested",
            }),
        );

        let exec = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "exec_command",
            json!({
                "cmd": "read line; printf 'stdin:%s\\n' \"$line\"",
                "yield_time_ms": 50,
                "max_output_tokens": 2000
            }),
            true,
        )
        .await?;
        let exec_json = m14_codex_parse_json_output("exec_command", &exec.output)?;
        let exec_session_id = exec_json
            .get("session_id")
            .and_then(Value::as_str)
            .ok_or_else(|| format!("exec_command did not return session_id: {}", exec.output))?;

        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "write_stdin",
            json!({
                "session_id": exec_session_id,
                "chars": "m14-codex-p0\\n",
                "yield_time_ms": 150,
                "max_output_tokens": 2000
            }),
            true,
        )
        .await?;

        let patch_path = "codex-p0-apply-patch.txt";
        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "apply_patch",
            json!({
                "patch": format!(
                    "*** Begin Patch\n*** Add File: {patch_path}\n+#969 apply_patch exercised through AppUI parity soak.\n*** End Patch\n"
                )
            }),
            true,
        )
        .await?;

        let denied = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "exec_command",
            json!({
                "cmd": "rm -rf /",
                "timeout_secs": 1
            }),
            false,
        )
        .await?;
        append_appui_evidence_jsonl(
            "approval-events.jsonl",
            json!({
                "event": "policy_denied",
                "issue": 969,
                "tool_name": "exec_command",
                "output": denied.output,
                "metadata": denied.structured_metadata,
            }),
        );

        let reviewer_artifact = artifact_dir.join("codex-p0-reviewer-report.md");
        let spawned = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "spawn_agent",
            json!({
                "agent_type": "explorer",
                "message": "Inspect #969 Codex P0 tool parity soak evidence.",
                "context": {"artifact_path": reviewer_artifact},
            }),
            true,
        )
        .await?;
        let spawned_json = m14_codex_parse_json_output("spawn_agent", &spawned.output)?;
        let agent_id = spawned_json
            .get("agent_id")
            .and_then(Value::as_str)
            .or_else(|| spawned_json.get("task_id").and_then(Value::as_str))
            .ok_or_else(|| format!("spawn_agent did not return agent_id: {}", spawned.output))?
            .to_owned();

        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "send_input",
            json!({
                "target": agent_id.clone(),
                "message": "Record reviewer input for #969 soak."
            }),
            true,
        )
        .await?;

        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "wait_agent",
            json!({
                "targets": [agent_id.clone()],
                "timeout_ms": 50
            }),
            true,
        )
        .await?;

        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "close_agent",
            json!({
                "target": agent_id.clone()
            }),
            true,
        )
        .await?;

        let resumed = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "resume_agent",
            json!({
                "target": agent_id.clone()
            }),
            true,
        )
        .await?;
        let resumed_json = m14_codex_parse_json_output("resume_agent", &resumed.output)?;
        let resumed_agent_id = resumed_json
            .get("resumed_agent_id")
            .and_then(Value::as_str)
            .unwrap_or(&agent_id)
            .to_owned();
        let _ = m14_codex_tool_call(
            &call_env,
            next_step!(),
            "close_agent",
            json!({
                "target": resumed_agent_id
            }),
            true,
        )
        .await?;

        write_appui_evidence_json(
            "runtime-policy-stamp.json",
            json!({
                "scenario": "m14_codex_p0_tool_parity",
                "issue": 969,
                "tool_contract_id": super::coding_tool_contract::CODING_TOOL_CONTRACT_ID,
                "tool_contract_version": super::coding_tool_contract::CODING_TOOL_CONTRACT_VERSION,
                "model_toolset": super::coding_tool_contract::CODING_MODEL_TOOLSET,
                "dynamic_tool_discovery": super::coding_tool_contract::CODING_DYNAMIC_TOOL_DISCOVERY,
                "workspace_root": workspace.to_string_lossy(),
                "session_id": session_id,
                "turn_id": turn_id,
                "p0_tools_exercised": super::coding_tool_contract::CODING_P0_REQUIRED_TOOL_NAMES,
            }),
        );

        Ok::<(), String>(())
    };

    tokio::select! {
        _ = interrupt_rx.recv() => M9FixtureOutcome::Interrupted,
        result = run => match result {
            Ok(()) => {
                append_appui_server_log("#969 Codex P0 tool parity soak completed");
                M9FixtureOutcome::Completed
            }
            Err(message) => M9FixtureOutcome::Errored {
                code: "codex_p0_tool_parity_failed",
                message,
            },
        }
    }
}

