    #[test]
    fn appui_prompt_context_bridge_preserves_current_user_turn() {
        let session_id = SessionKey::new("api", "context-current-user");
        let history = vec![
            test_message(MessageRole::User, "old request"),
            test_message(MessageRole::Assistant, "old answer"),
        ];
        let manager = Arc::new(StdMutex::new(ContextManager::from_session_history(
            session_id.to_string(),
            None,
            &history,
        )));
        let dir = tempfile::tempdir().unwrap();
        let bridge = AppUiPromptContextBridge::new(
            session_id.clone(),
            dir.path().to_path_buf(),
            manager,
            false,
        );
        let mut prompt = vec![test_message(MessageRole::System, "runtime system")];
        prompt.extend(history);
        prompt.push(test_message(MessageRole::User, "current request"));

        let report = bridge
            .prepare_prompt(
                PromptContextRequest {
                    phase: PromptContextPhase::TurnStart,
                    iteration: 1,
                    provider_name: "test".to_string(),
                    model_id: "large-context".to_string(),
                    context_window: 16_000,
                },
                &mut prompt,
            )
            .expect("context manager bridge should prepare prompt");

        assert!(report.prompt_replaced);
        assert!(
            prompt.iter().any(|message| {
                message.role == MessageRole::System && message.content == "runtime system"
            }),
            "managed prompt should keep the runtime system instruction"
        );
        assert!(
            prompt.iter().any(|message| {
                message.role == MessageRole::User && message.content == "current request"
            }),
            "managed prompt must keep the current user turn"
        );
        assert_eq!(
            prompt
                .iter()
                .filter(|message| {
                    message.role == MessageRole::User && message.content == "old request"
                })
                .count(),
            1,
            "known history should not be duplicated while adding the current turn"
        );
        assert!(
            crate::context_manager::context_ledger_path(dir.path(), &session_id.to_string())
                .exists(),
            "AppUI prompt-context preparation should persist the canonical context ledger"
        );
    }

    /// UPCR-2026-026 follow-up: the in-loop (mid-turn) compaction pass must
    /// emit `ContextCompactionStarted` → `ContextCompactionCompleted` through
    /// the bridge's notify hook. It previously compacted SILENTLY — the only
    /// emitting site (the pre-turn bridge) was then starved forever by the
    /// persisted post-compaction snapshot, so a session whose context filled
    /// mid-turn never showed any compaction UX.
    #[test]
    fn in_loop_compaction_emits_lifecycle_notifications() {
        let session_id = SessionKey::new("api", "context-inloop-events");
        // Enough history that the items estimate dwarfs 70% of a tiny window.
        let history: Vec<Message> = (0..10)
            .flat_map(|idx| {
                vec![
                    test_message(
                        MessageRole::User,
                        &format!("req {idx}: {}", "x".repeat(400)),
                    ),
                    test_message(
                        MessageRole::Assistant,
                        &format!("ans {idx}: {}", "y".repeat(400)),
                    ),
                ]
            })
            .collect();
        let manager = Arc::new(StdMutex::new(ContextManager::from_session_history(
            session_id.to_string(),
            None,
            &history,
        )));
        let dir = tempfile::tempdir().unwrap();
        let captured: Arc<StdMutex<Vec<UiNotification>>> = Arc::new(StdMutex::new(Vec::new()));
        let sink = captured.clone();
        let bridge = AppUiPromptContextBridge::new(
            session_id.clone(),
            dir.path().to_path_buf(),
            manager,
            false,
        )
        .with_context_lifecycle_notify(Arc::new(move |notification| {
            sink.lock()
                .unwrap_or_else(|error| error.into_inner())
                .push(notification);
        }));

        let mut prompt = vec![test_message(MessageRole::System, "runtime system")];
        prompt.extend(history);
        prompt.push(test_message(MessageRole::User, "current request"));

        let report = bridge
            .prepare_prompt(
                PromptContextRequest {
                    phase: PromptContextPhase::TurnStart,
                    iteration: 1,
                    provider_name: "test".to_string(),
                    model_id: "tiny-context".to_string(),
                    // threshold = 70% of 300 = 210 tokens — trivially exceeded.
                    context_window: 300,
                },
                &mut prompt,
            )
            .expect("context manager bridge should prepare prompt");
        assert!(
            report.compaction_performed,
            "the tiny window must force an in-loop compaction"
        );

        let events = captured.lock().unwrap_or_else(|error| error.into_inner());
        let started = events
            .iter()
            .position(|n| matches!(n, UiNotification::ContextCompactionStarted(_)))
            .expect("in-loop compaction must emit ContextCompactionStarted");
        let completed = events
            .iter()
            .position(|n| matches!(n, UiNotification::ContextCompactionCompleted(_)))
            .expect("in-loop compaction must emit ContextCompactionCompleted");
        assert!(
            started < completed,
            "started must precede completed in the emitted order"
        );
        let UiNotification::ContextCompactionStarted(event) = &events[started] else {
            unreachable!()
        };
        assert_eq!(event.session_id, session_id);
        assert_eq!(event.trigger, "agent_loop:turn_start");
        assert_eq!(event.threshold_tokens, 210);
        let UiNotification::ContextCompactionCompleted(done) = &events[completed] else {
            unreachable!()
        };
        assert_eq!(done.session_id, session_id);
        assert_eq!(done.compaction.trigger, "agent_loop:turn_start");
    }

    #[test]
    fn voice_turn_bridge_caps_outgoing_prompt_only() {
        // Lever 2: a voice turn caps the OUTGOING projection at the voice
        // budget so the spoken-turn prefill stays small; a text turn leaves it
        // uncapped. The cap lives on `outgoing_prompt_policy` only — the
        // record/coverage/compaction passes use the uncapped `prompt_policy`,
        // so the persisted transcript is never re-recorded from a trimmed view.
        let session_id = SessionKey::new("api", "voice-cap");
        let dir = tempfile::tempdir().unwrap();
        let manager = Arc::new(StdMutex::new(ContextManager::from_session_history(
            session_id.to_string(),
            None,
            &[],
        )));
        let request = PromptContextRequest {
            phase: PromptContextPhase::TurnStart,
            iteration: 1,
            provider_name: "test".to_string(),
            model_id: "m".to_string(),
            context_window: 16_000,
        };

        let voice = AppUiPromptContextBridge::new(
            session_id.clone(),
            dir.path().to_path_buf(),
            manager.clone(),
            true,
        );
        assert_eq!(
            voice
                .outgoing_prompt_policy(&request)
                .max_prompt_token_estimate,
            Some(AppUiPromptContextBridge::voice_prompt_budget()),
            "voice turns must cap the outgoing prompt projection"
        );

        let text =
            AppUiPromptContextBridge::new(session_id, dir.path().to_path_buf(), manager, false);
        assert_eq!(
            text.outgoing_prompt_policy(&request)
                .max_prompt_token_estimate,
            None,
            "text turns must leave the outgoing prompt uncapped"
        );
    }

    /// #1134 acceptance — when an AppUI loop turn uses a spawn_only /
    /// send_file path that persists a background assistant message
    /// AFTER the model's final reply, the pre-#1134 shape walks the
    /// session history with `.last()` and selects the background row
    /// — which contains no `<<loop-next-in: ...>>` hint — so
    /// `apply_self_paced_response` falls back to the default delay.
    ///
    /// The fix routes the agent task's `response.content` out through
    /// a oneshot so the post-turn block parses the hint directly off
    /// the LLM's EndTurn payload. This test pins the contract:
    /// feeding the helper a captured `<<loop-next-in: 60s>>` reply
    /// AND a session-history fallback that would (incorrectly) yield
    /// a background row must pick the captured reply, and
    /// `apply_self_paced_response` must reschedule at ~60s — NOT the
    /// `SELF_PACED_DEFAULT_DELAY_SECONDS` fallback.
    #[test]
    fn appui_loop_uses_response_content_not_session_history_for_self_paced() {
        // Build a private orchestrator so the test does not touch the
        // process-wide `default_agent_orchestrator()` static; running
        // in parallel with the appui_*_loop_*_drains tests that DO
        // share the static would otherwise contaminate their loop
        // counts.
        use crate::api::agent_orchestrator::InProcessAgentOrchestrator;

        // `SELF_PACED_DEFAULT_DELAY_SECONDS` is module-private
        // (`agent_orchestrator.rs` line 49: `const ... = 60 * 15`).
        // Mirror the constant here so the test pins the EXACT value
        // the production fallback would stamp — if the production
        // default changes, this test goes red as a tripwire,
        // forcing a follow-up review.
        const SELF_PACED_DEFAULT_DELAY_SECONDS_MIRROR: u64 = 60 * 15;

        // Simulated turn timeline (exactly the bug scenario): the
        // model emitted a self-paced hint, then a spawn_only /
        // send_file companion row was persisted afterwards. The
        // history fallback's `.last()` would pick the background
        // row, which has no hint.
        let model_reply = "status report <<loop-next-in: 60s>>";
        let background_row = "[background] sent file: report.pdf";
        let history = vec![
            test_message(MessageRole::User, "loop fire prompt"),
            test_message(MessageRole::Assistant, model_reply),
            // The bug: a background assistant row lands AFTER the
            // model's EndTurn reply.
            test_message(MessageRole::Assistant, background_row),
        ];
        let pre_assistant_count = 0;

        // Pre-#1134 behaviour: history fallback alone picks the
        // background row.
        let fallback_only =
            appui_history_last_non_empty_assistant_after(&history, pre_assistant_count);
        assert_eq!(
            fallback_only.as_deref(),
            Some(background_row),
            "fallback alone reproduces the bug — picks the background row, not the model reply"
        );

        // Post-#1134 behaviour: the captured `response.content` wins
        // even though the fallback would (incorrectly) yield the
        // background row.
        let assistant_reply = appui_loop_assistant_reply_for_self_paced(
            Some(model_reply),
            // Compute the fallback the same way the production
            // post-turn block does — this is the value `.last()`
            // would have returned.
            appui_history_last_non_empty_assistant_after(&history, pre_assistant_count),
        );
        assert_eq!(
            assistant_reply.as_deref(),
            Some(model_reply),
            "captured response.content must win over the session-history fallback"
        );

        // End-to-end: feed the picked reply into the orchestrator's
        // self-paced reschedule and confirm the next_run_at_ms lands
        // ~60s out (NOT the default delay).
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id =
            SessionKey::with_profile("tenant-a", "api", "appui-loop-self-paced-response");
        let created = orchestrator
            .create_loop(LoopCreateRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                prompt: Some("self-paced loop".into()),
                command: None,
                interval_seconds: None,
                mode: Some("self_paced".into()),
            })
            .expect("create self_paced loop");
        let loop_id = created["loop_id"].as_str().expect("loop id").to_owned();

        let applied = orchestrator
            .apply_self_paced_response(
                &loop_id,
                "tenant-a",
                assistant_reply.as_deref().expect("picked assistant reply"),
            )
            .expect("apply self-paced response");
        assert_eq!(
            applied,
            Some(Duration::from_secs(60)),
            "captured response.content must yield the 60s hint, not the default delay"
        );
        assert_ne!(
            applied,
            Some(Duration::from_secs(SELF_PACED_DEFAULT_DELAY_SECONDS_MIRROR)),
            "captured response.content must NOT fall back to SELF_PACED_DEFAULT_DELAY_SECONDS"
        );

        // Negative control: had we taken the background row instead
        // (the pre-#1134 shape), the parsed delay would be `None`
        // and apply_self_paced_response would stamp the default.
        let bug_path = orchestrator
            .apply_self_paced_response(&loop_id, "tenant-a", background_row)
            .expect("apply self-paced response (bug path)");
        assert_eq!(
            bug_path, None,
            "the pre-#1134 history-fallback path returns None (no hint), stamping the default delay"
        );
    }

    /// #1134 — when the oneshot didn't fire (interrupt / agent error
    /// path), the post-turn block must fall back to the session
    /// history scan. This pins that contract on the picker helper.
    #[test]
    fn appui_loop_self_paced_picker_falls_back_to_history_when_capture_missing() {
        let history_pick = Some("status report <<loop-next-in: 60s>>".to_owned());
        let assistant_reply = appui_loop_assistant_reply_for_self_paced(None, history_pick.clone());
        assert_eq!(assistant_reply, history_pick);

        // Empty captured content is treated as "no reply" (matches
        // the non-empty filter the history walk applies). We do NOT
        // fall back to history in that case — the agent explicitly
        // delivered a blank EndTurn payload.
        let blank_capture = appui_loop_assistant_reply_for_self_paced(Some(""), history_pick);
        assert_eq!(
            blank_capture, None,
            "empty captured content must not stamp a default-delay reschedule via history fallback"
        );

        // A fire with NO capture and NO history reply (interrupt / agent
        // error before anything persisted) must still reschedule: the
        // picker yields an empty reply, which carries no sentinel, so the
        // orchestrator stamps the DEFAULT delay. The old `None` here parked
        // the loop at `next_run_at_ms: None` — permanently dead after one
        // interrupted turn.
        let reply_less = appui_loop_assistant_reply_for_self_paced(None, None);
        assert_eq!(
            reply_less.as_deref(),
            Some(""),
            "a reply-less fire must reschedule with the default delay, not kill the loop"
        );
    }

