    // ========================================================================
    // M10 Phase 1: `event.spawn_complete.v1` capability gating
    // ========================================================================

    /// Pure unit-level coverage of the dual filter — no WS / forwarder
    /// machinery. Documents the four corners of the negotiation matrix
    /// against the two relevant event shapes.
    #[test]
    fn capability_filter_routes_spawn_complete_dual_gating() {
        let session = SessionKey("local:filter".into());
        let bg_persisted =
            UiProtocolLedgerEvent::Notification(background_message_persisted_for(&session));
        let spawn_complete = UiProtocolLedgerEvent::Notification(turn_spawn_complete_for(&session));

        // Old client (no spawn_complete capability, has message_persisted):
        // sees `message/persisted` (Background source preserved); does NOT
        // see `turn/spawn_complete`.
        let old = features_for_spawn_complete_test(true, false);
        assert!(
            live_event_passes_capability_filter(&bg_persisted, old),
            "old client must keep receiving the legacy message/persisted shape",
        );
        assert!(
            !live_event_passes_capability_filter(&spawn_complete, old),
            "old client must not receive the new turn/spawn_complete shape",
        );

        // New client (has both capabilities): sees `turn/spawn_complete`;
        // the duplicate `message/persisted` (source: background) is
        // suppressed so the same logical event is delivered exactly once.
        let new = features_for_spawn_complete_test(true, true);
        assert!(
            !live_event_passes_capability_filter(&bg_persisted, new),
            "new client must NOT receive the duplicate message/persisted background row",
        );
        assert!(
            live_event_passes_capability_filter(&spawn_complete, new),
            "new client must receive the turn/spawn_complete envelope",
        );

        // New client without message_persisted negotiation: still gets
        // turn/spawn_complete. (The two capabilities are independent —
        // a forward-only client can opt into the new shape without ever
        // having shipped the older one.)
        let new_only = features_for_spawn_complete_test(false, true);
        assert!(
            !live_event_passes_capability_filter(&bg_persisted, new_only),
            "client without message_persisted does not see message/persisted regardless",
        );
        assert!(
            live_event_passes_capability_filter(&spawn_complete, new_only),
            "spawn_complete-only client receives turn/spawn_complete",
        );

        // Legacy client with NO negotiated features at all: sees neither
        // (the old gate already blocks message/persisted; the new gate
        // blocks turn/spawn_complete).
        let neither = features_for_spawn_complete_test(false, false);
        assert!(!live_event_passes_capability_filter(&bg_persisted, neither));
        assert!(!live_event_passes_capability_filter(
            &spawn_complete,
            neither
        ));

        // Sanity: a non-spawn `message/persisted` (source != background,
        // e.g. a regular assistant row) is unaffected by the spawn_complete
        // gate. Only the duplicate-suppression branch keys on
        // `MessagePersistedSource::Background`.
        let regular = UiProtocolLedgerEvent::Notification(message_persisted_for(&session));
        assert!(
            live_event_passes_capability_filter(&regular, new),
            "non-background message/persisted must still flow to new clients",
        );
    }

    /// UPCR-2026-014 M9-α-9 `event.file_attached.v1` capability gate.
    /// Old clients that never advertised the feature MUST NOT receive
    /// `file/attached` envelopes — they keep relying on `media` on
    /// `message/persisted` / `turn/spawn_complete`. New clients that
    /// negotiated the feature MUST receive the dedicated envelope so
    /// the slides soak's "PPTX on disk but no button on SPA" regression
    /// can be closed by a redundant wire signal.
    #[test]
    fn capability_filter_routes_file_attached_gating() {
        let session = SessionKey("local:file-attached-gate".into());
        let file_attached = UiProtocolLedgerEvent::Notification(file_attached_for(&session));

        // Old client: never observe the new envelope.
        let old = features_for_file_attached_test(false);
        assert!(
            !live_event_passes_capability_filter(&file_attached, old),
            "clients without event.file_attached.v1 must not receive file/attached envelopes",
        );

        // New client: receive the envelope.
        let new = features_for_file_attached_test(true);
        assert!(
            live_event_passes_capability_filter(&file_attached, new),
            "clients with event.file_attached.v1 receive the per-artefact envelope",
        );

        // Independence from spawn_complete: a new client that
        // negotiated ONLY file_attached (no message_persisted, no
        // spawn_complete) still sees the file delivery. This matches
        // the redundancy goal — file_attached is the safety net for
        // clients whose richer-envelope reducers might drop the
        // delivery.
        let only_file_attached = ConnectionUiFeatures {
            file_attached: true,
            header_present: true,
            ..ConnectionUiFeatures::default()
        };
        assert!(
            live_event_passes_capability_filter(&file_attached, only_file_attached),
            "file_attached gate is independent of spawn_complete / message_persisted",
        );
    }

    #[test]
    fn capability_filter_routes_context_lifecycle_gating() {
        let session = SessionKey("local:context-filter".into());
        let compaction =
            UiProtocolLedgerEvent::Notification(context_compaction_completed_for(&session));
        let normalization =
            UiProtocolLedgerEvent::Notification(context_normalization_reported_for(&session));

        let old = ConnectionUiFeatures {
            context_lifecycle_v1: false,
            header_present: true,
            ..ConnectionUiFeatures::default()
        };
        assert!(
            !live_event_passes_capability_filter(&compaction, old),
            "clients without context.lifecycle.v1 must not receive compaction events",
        );
        assert!(
            !live_event_passes_capability_filter(&normalization, old),
            "clients without context.lifecycle.v1 must not receive normalization events",
        );

        let new = ConnectionUiFeatures {
            context_lifecycle_v1: true,
            header_present: true,
            ..ConnectionUiFeatures::default()
        };
        assert!(
            live_event_passes_capability_filter(&compaction, new),
            "clients with context.lifecycle.v1 receive compaction events",
        );
        assert!(
            live_event_passes_capability_filter(&normalization, new),
            "clients with context.lifecycle.v1 receive normalization events",
        );
    }

    // ========================================================================
    // UPCR-2026-014 M9-γ — per-connection envelope/legacy mutual exclusion.
    // ========================================================================

    fn projection_envelope_event_for(session: &SessionKey) -> UiNotification {
        UiNotification::Envelope(octos_core::ui_protocol::EnvelopeNotification {
            session_id: session.clone(),
            topic: None,
            envelope: octos_core::ui_protocol::Envelope {
                thread_id: "thread-1".into(),
                seq: 1,
                client_message_id: None,
                payload: Payload::AssistantDelta { text: "x".into() },
            },
        })
    }

    fn features_for_projection_envelope_test(projection_envelope: bool) -> ConnectionUiFeatures {
        ConnectionUiFeatures {
            // Pre-existing capability flags are enabled so the *only*
            // gate being exercised is the M9-γ projection.envelope.v1
            // mutual exclusion — the test would otherwise be polluted by
            // the `message_persisted` and `spawn_complete` gates above.
            projection_envelope,
            message_persisted: true,
            spawn_complete: true,
            file_attached: true,
            header_present: true,
            ..ConnectionUiFeatures::default()
        }
    }

    /// Per-connection envelope/legacy mutual exclusion is the cutover
    /// mechanism for M9-γ (spec § 14.7). A connection that negotiated
    /// `projection.envelope.v1` sees ONLY canonical envelopes for the
    /// events that surface had legacy analogs; a connection that did
    /// NOT negotiate sees ONLY the legacy events and never the envelope.
    #[test]
    fn capability_filter_envelope_legacy_mutual_exclusion() {
        let session = SessionKey("local:envelope-gate".into());
        let envelope_event =
            UiProtocolLedgerEvent::Notification(projection_envelope_event_for(&session));
        let delta_event =
            UiProtocolLedgerEvent::Notification(UiNotification::MessageDelta(MessageDeltaEvent {
                session_id: session.clone(),
                topic: None,
                turn_id: TurnId::new(),
                text: "hello".into(),
            }));
        let tool_started =
            UiProtocolLedgerEvent::Notification(UiNotification::ToolStarted(ToolStartedEvent {
                session_id: session.clone(),
                topic: None,
                turn_id: TurnId::new(),
                tool_call_id: "tc-1".into(),
                tool_name: "shell".into(),
                arguments: None,
            }));
        let tool_progress =
            UiProtocolLedgerEvent::Notification(UiNotification::ToolProgress(ToolProgressEvent {
                session_id: session.clone(),
                topic: None,
                turn_id: TurnId::new(),
                tool_call_id: "tc-1".into(),
                message: Some("step".into()),
                progress_pct: None,
            }));
        let tool_completed = UiProtocolLedgerEvent::Notification(UiNotification::ToolCompleted(
            ToolCompletedEvent {
                session_id: session.clone(),
                topic: None,
                turn_id: TurnId::new(),
                tool_call_id: "tc-1".into(),
                tool_name: "shell".into(),
                success: Some(true),
                output_preview: None,
                duration_ms: None,
            },
        ));
        let turn_completed = UiProtocolLedgerEvent::Notification(UiNotification::TurnCompleted(
            TurnCompletedEvent {
                session_id: session.clone(),
                topic: None,
                turn_id: TurnId::new(),
                cursor: None,
                tokens_in: None,
                tokens_out: None,
                session_result: None,
            },
        ));
        let message_persisted =
            UiProtocolLedgerEvent::Notification(message_persisted_for(&session));
        let file_attached = UiProtocolLedgerEvent::Notification(file_attached_for(&session));

        // Legacy client (projection_envelope=false): receives ALL legacy
        // events; envelope is filtered out.
        let legacy = features_for_projection_envelope_test(false);
        assert!(
            !live_event_passes_capability_filter(&envelope_event, legacy),
            "legacy client must NOT receive projection/envelope notifications",
        );
        for (label, ev) in [
            ("MessageDelta", &delta_event),
            ("ToolStarted", &tool_started),
            ("ToolProgress", &tool_progress),
            ("ToolCompleted", &tool_completed),
            ("TurnCompleted", &turn_completed),
            ("MessagePersisted", &message_persisted),
            ("FileAttached", &file_attached),
        ] {
            assert!(
                live_event_passes_capability_filter(ev, legacy),
                "legacy client must STILL receive legacy {label} notifications",
            );
        }

        // Envelope client (projection_envelope=true): receives ONLY the
        // envelope; legacy variants superseded by envelopes are
        // filtered out.
        let envelope_client = features_for_projection_envelope_test(true);
        assert!(
            live_event_passes_capability_filter(&envelope_event, envelope_client),
            "envelope client receives projection/envelope notifications",
        );
        for (label, ev) in [
            ("MessageDelta", &delta_event),
            ("ToolStarted", &tool_started),
            ("ToolProgress", &tool_progress),
            ("ToolCompleted", &tool_completed),
            ("TurnCompleted", &turn_completed),
            ("MessagePersisted", &message_persisted),
            ("FileAttached", &file_attached),
        ] {
            assert!(
                !live_event_passes_capability_filter(ev, envelope_client),
                "envelope client must NOT receive legacy {label} notifications",
            );
        }
    }

    /// UPCR-2026-014 M9-γ per-payload dual-emit: every legacy
    /// notification surfaced by `forward_progress_event` triggers a
    /// parallel `projection/envelope` ledger append. The test exercises
    /// the helper that wires the dual-emit
    /// (`emit_envelope_for_legacy_notification`) so a future refactor
    /// can't silently drop a variant from the dual surface.
    #[test]
    fn emit_envelope_carries_tool_fidelity_previews() {
        // The tool-card fidelity lane: ToolStarted.arguments →
        // ToolStart.arguments_preview (key: value rendering, bounded) and
        // ToolCompleted.output_preview/duration_ms → ToolEnd (re-bounded).
        let ledger = UiProtocolLedger::new(32);
        let session_id = SessionKey("local:fidelity-emit".into());
        let turn_id = TurnId::new();

        let giant = "æ".repeat(9000);
        emit_envelope_for_legacy_notification(
            &ledger,
            &session_id,
            &UiNotification::ToolStarted(ToolStartedEvent {
                session_id: session_id.clone(),
                topic: None,
                turn_id: turn_id.clone(),
                tool_call_id: "tc-fid".into(),
                tool_name: "shell".into(),
                arguments: Some(serde_json::json!({
                    "command": "cargo test",
                    "blob": giant,
                })),
            }),
        );
        emit_envelope_for_legacy_notification(
            &ledger,
            &session_id,
            &UiNotification::ToolCompleted(ToolCompletedEvent {
                session_id: session_id.clone(),
                topic: None,
                turn_id: turn_id.clone(),
                tool_call_id: "tc-fid".into(),
                tool_name: "shell".into(),
                success: Some(true),
                output_preview: Some("test result: ok. 815 passed".into()),
                duration_ms: Some(4321),
            }),
        );

        let baseline = UiCursor {
            stream: session_id.0.clone(),
            seq: 0,
        };
        let replay = ledger.replay_after(&session_id, Some(&baseline)).unwrap();
        let payloads: Vec<&Payload> = replay
            .iter()
            .filter_map(|e| match &e.event {
                UiProtocolLedgerEvent::Notification(UiNotification::Envelope(env)) => {
                    Some(&env.envelope.payload)
                }
                _ => None,
            })
            .collect();

        let Some(Payload::ToolStart {
            arguments_preview: Some(preview),
            ..
        }) = payloads.first()
        else {
            panic!("expected enriched ToolStart, got {payloads:?}");
        };
        assert!(
            preview.contains("command: \"cargo test\""),
            "object args render as key: value pairs, got {preview}"
        );
        assert!(
            preview.chars().count()
                <= octos_core::ui_protocol::ENVELOPE_TOOL_ARGUMENTS_PREVIEW_MAX + 1,
            "arguments preview must be bounded (UTF-8-safe), got {} chars",
            preview.chars().count()
        );
        let Some(Payload::ToolEnd {
            output_preview: Some(output),
            duration_ms: Some(duration),
            ..
        }) = payloads.get(1)
        else {
            panic!("expected enriched ToolEnd, got {payloads:?}");
        };
        assert_eq!(output, "test result: ok. 815 passed");
        assert_eq!(*duration, 4321);

        // `{}` arguments render empty — spec says OMIT, not empty-string.
        emit_envelope_for_legacy_notification(
            &ledger,
            &session_id,
            &UiNotification::ToolStarted(ToolStartedEvent {
                session_id: session_id.clone(),
                topic: None,
                turn_id: turn_id.clone(),
                tool_call_id: "tc-empty".into(),
                tool_name: "noop".into(),
                arguments: Some(serde_json::json!({})),
            }),
        );
        let replay = ledger.replay_after(&session_id, Some(&baseline)).unwrap();
        let empty_start = replay
            .iter()
            .filter_map(|e| match &e.event {
                UiProtocolLedgerEvent::Notification(UiNotification::Envelope(env)) => {
                    match &env.envelope.payload {
                        Payload::ToolStart {
                            tool_call_id,
                            arguments_preview,
                            ..
                        } if tool_call_id == "tc-empty" => Some(arguments_preview.clone()),
                        _ => None,
                    }
                }
                _ => None,
            })
            .next()
            .expect("tc-empty envelope present");
        assert_eq!(empty_start, None, "empty args must omit the preview");
    }

    #[test]
    fn emit_envelope_for_legacy_notification_covers_every_progress_variant() {
        let ledger = UiProtocolLedger::new(32);
        let session_id = SessionKey("local:dual-emit".into());

        // The progress-mapper emits these four notification variants —
        // each must yield a corresponding envelope.
        let turn_id = TurnId::new();
        let cases: Vec<(UiNotification, &'static str)> = vec![
            (
                UiNotification::MessageDelta(MessageDeltaEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    text: "delta".into(),
                }),
                "assistant_delta",
            ),
            (
                UiNotification::ReasoningDelta(ReasoningDeltaEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    text: "reasoning".into(),
                }),
                "reasoning_delta",
            ),
            (
                UiNotification::ToolStarted(ToolStartedEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    tool_call_id: "tc-1".into(),
                    tool_name: "shell".into(),
                    arguments: None,
                }),
                "tool_start",
            ),
            (
                UiNotification::ToolProgress(ToolProgressEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    tool_call_id: "tc-1".into(),
                    message: Some("hello".into()),
                    progress_pct: None,
                }),
                "tool_progress",
            ),
            (
                UiNotification::ToolCompleted(ToolCompletedEvent {
                    session_id: session_id.clone(),
                    topic: None,
                    turn_id: turn_id.clone(),
                    tool_call_id: "tc-1".into(),
                    tool_name: "shell".into(),
                    success: Some(true),
                    output_preview: None,
                    duration_ms: None,
                }),
                "tool_end",
            ),
        ];

        let mut expected_types: Vec<&str> = cases.iter().map(|(_, t)| *t).collect();

        for (notif, _expected_type) in &cases {
            emit_envelope_for_legacy_notification(&ledger, &session_id, notif);
        }

        let baseline = UiCursor {
            stream: session_id.0.clone(),
            seq: 0,
        };
        let replay = ledger.replay_after(&session_id, Some(&baseline)).unwrap();
        let envelope_types: Vec<String> = replay
            .iter()
            .filter_map(|e| match &e.event {
                UiProtocolLedgerEvent::Notification(UiNotification::Envelope(env)) => {
                    match &env.envelope.payload {
                        Payload::AssistantDelta { .. } => Some("assistant_delta".into()),
                        Payload::ReasoningDelta { .. } => Some("reasoning_delta".into()),
                        Payload::ToolStart { .. } => Some("tool_start".into()),
                        Payload::ToolProgress { .. } => Some("tool_progress".into()),
                        Payload::ToolEnd { .. } => Some("tool_end".into()),
                        Payload::FileAttached { .. } => Some("file_attached".into()),
                        Payload::TurnCompleted { .. } => Some("turn_completed".into()),
                        Payload::AssistantPersisted { .. } => Some("assistant_persisted".into()),
                        Payload::UserMessage { .. } => Some("user_message".into()),
                    }
                }
                _ => None,
            })
            .collect();

        // Order-sensitive: envelopes are appended in the order the
        // notifications arrive, so we expect the exact slice.
        expected_types.sort();
        let mut got_types = envelope_types.clone();
        got_types.sort();
        assert_eq!(
            got_types,
            expected_types
                .iter()
                .map(|s| (*s).to_string())
                .collect::<Vec<_>>(),
            "every progress-variant must dual-emit; got {envelope_types:?}",
        );
    }

    /// Replay-vs-live divergence: the live-emit hard barrier in
    /// `UiProtocolLedger::emit_envelope` DROPS post-completion envelopes,
    /// but ledger replay (`replay_after`) returns the FULL durable
    /// history. This is the documented semantics from spec § 14.6 — a
    /// client that reconnects with a pre-completion cursor still sees
    /// every envelope that was emitted, and applies the barrier itself.
    #[test]
    fn live_emit_hard_barrier_does_not_affect_ledger_replay() {
        let ledger = UiProtocolLedger::new(32);
        let session_id = SessionKey("local:replay-vs-live".into());
        let thread_id = "thread-rl".to_owned();

        // Live-emit path: AssistantDelta + TurnCompleted, then a
        // post-completion AssistantDelta which the hard barrier drops.
        let a = ledger
            .emit_envelope(
                &session_id,
                thread_id.clone(),
                Payload::AssistantDelta { text: "a".into() },
                None,
            )
            .expect("first emit accepted");
        let completed = ledger
            .emit_envelope(
                &session_id,
                thread_id.clone(),
                Payload::TurnCompleted {
                    token_usage: octos_core::ui_protocol::EnvelopeTokenUsage::default(),
                },
                None,
            )
            .expect("turn_completed accepted");
        let dropped = ledger.emit_envelope(
            &session_id,
            thread_id.clone(),
            Payload::AssistantDelta {
                text: "should be barrier-dropped".into(),
            },
            None,
        );
        assert!(
            dropped.is_none(),
            "live-emit must drop the post-completion envelope at the barrier",
        );

        // Now: pre-seed the ledger with a raw post-completion envelope
        // (bypassing emit_envelope) so the on-disk / in-memory ring
        // carries it. This models the "old durable record from before
        // the barrier was tightened" replay scenario.
        let raw = UiNotification::Envelope(octos_core::ui_protocol::EnvelopeNotification {
            session_id: session_id.clone(),
            topic: None,
            envelope: octos_core::ui_protocol::Envelope {
                thread_id: thread_id.clone(),
                seq: 99,
                client_message_id: None,
                payload: Payload::AssistantDelta {
                    text: "raw post-completion".into(),
                },
            },
        });
        let raw_appended = ledger.append_notification(raw);

        // Replay returns everything appended — the live-emit barrier
        // does NOT prune the ledger, only the live wire delivery.
        let baseline = UiCursor {
            stream: session_id.0.clone(),
            seq: 0,
        };
        let replay = ledger.replay_after(&session_id, Some(&baseline)).unwrap();
        let envelope_count = replay
            .iter()
            .filter(|e| {
                matches!(
                    &e.event,
                    UiProtocolLedgerEvent::Notification(UiNotification::Envelope(_))
                )
            })
            .count();
        assert!(
            envelope_count >= 3,
            "ledger replay must return ALL envelopes including post-completion raw appends \
             (live-emit barrier applies only at emit, not at replay); got {envelope_count}",
        );
        // Sanity: the original live-accepted envelopes are present.
        let cursors: Vec<u64> = replay.iter().map(|e| e.cursor.seq).collect();
        assert!(cursors.contains(&a.cursor.seq));
        assert!(cursors.contains(&completed.cursor.seq));
        assert!(cursors.contains(&raw_appended.cursor.seq));
    }

    /// End-to-end through the live forwarder for a NEW client (negotiated
    /// `event.spawn_complete.v1`): asserts they receive `turn/spawn_complete`
    /// AND the duplicate `message/persisted` (source: background) is
    /// suppressed. The combination is what kills the splice-merge
    /// double-render.
    #[tokio::test]
    async fn live_forwarder_routes_spawn_complete_to_new_client() {
        let (ws, mut rx) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:newfeat".into());
        let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        let live_rx = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws.connection_id(),
            features_for_spawn_complete_test(true, true),
            None,
            live_rx,
            forwarders.clone(),
        )
        .await;

        // Producer side fires both — the persistence-driven
        // `message/persisted` (via `MessageCommitObserver`) AND the new
        // envelope (direct ledger append from `BackgroundResultSender`).
        ledger.append_notification(background_message_persisted_for(&session_id));
        ledger.append_notification(turn_spawn_complete_for(&session_id));

        // The new client must observe exactly one frame: the spawn_complete
        // envelope. The duplicate background message/persisted is filtered.
        let frame = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
            .await
            .expect("expected the spawn_complete envelope within 1s")
            .expect("ws still open");
        assert_eq!(
            frame_method(&frame).as_deref(),
            Some(octos_core::ui_protocol::methods::TURN_SPAWN_COMPLETE),
            "first frame must be turn/spawn_complete (background message/persisted suppressed)",
        );

        // No further frames should arrive — the background message/persisted
        // was filtered.
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        assert!(
            rx.try_recv().is_err(),
            "no second frame: background message/persisted is suppressed for new clients",
        );

        abort_live_forwarders(&forwarders, &ledger).await;
    }

    /// Codex P1: when the BackgroundResultSender persist scope is
    /// active, `current_message_persisted_source` must report
    /// `Background` regardless of the `Message` role. Outside the scope
    /// it falls back to the role-derived default — the pre-M10
    /// behaviour stays intact for every other persist path.
    #[tokio::test]
    async fn message_persisted_source_override_routes_through_task_local() {
        // Outside any scope: role-derived default.
        let default_for_assistant = current_message_persisted_source(MessageRole::Assistant);
        assert_eq!(default_for_assistant, MessagePersistedSource::Assistant);
        let default_for_tool = current_message_persisted_source(MessageRole::Tool);
        assert_eq!(default_for_tool, MessagePersistedSource::Tool);

        // Inside the override scope (mirrors what the
        // `BackgroundResultSender` closure does): every role maps to
        // `Background`.
        let bg = MESSAGE_PERSISTED_SOURCE_OVERRIDE
            .scope(Some(MessagePersistedSource::Background), async {
                (
                    current_message_persisted_source(MessageRole::Assistant),
                    current_message_persisted_source(MessageRole::Tool),
                )
            })
            .await;
        assert_eq!(bg.0, MessagePersistedSource::Background);
        assert_eq!(bg.1, MessagePersistedSource::Background);

        // After the scope ends, the default behaviour is restored.
        let after = current_message_persisted_source(MessageRole::Assistant);
        assert_eq!(after, MessagePersistedSource::Assistant);
    }

    /// Issue #889: a contract-verified `fm_tts` spawn result must persist
    /// its completion row after the MP3 reaches disk. A false return from
    /// this helper is a real session-ledger inconsistency, so pin the
    /// success path with media and the background source override that the
    /// production `BackgroundResultSender` uses.
    #[tokio::test(flavor = "current_thread")]
    async fn background_result_sender_persists_contract_verified_media_row() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let media_dir = tmp
            .path()
            .join("users")
            .join("dspfac%3Aapi%3Am11h-yangmi")
            .join("workspace")
            .join("skill-output");
        std::fs::create_dir_all(&media_dir).expect("media dir");
        let mp3_path = media_dir.join("yangmi_hello_1778515952.mp3");
        std::fs::write(&mp3_path, b"ID3 issue-889 regression").expect("mp3 fixture");

        let sessions = Arc::new(tokio::sync::Mutex::new(
            octos_bus::SessionManager::open(tmp.path()).expect("session manager"),
        ));
        let session_id = SessionKey("dspfac:api:m11h-yangmi-issue-889".into());
        let thread_id = "turn-issue-889";
        let media = vec![mp3_path.to_string_lossy().into_owned()];

        let persisted = MESSAGE_PERSISTED_SOURCE_OVERRIDE
            .scope(
                Some(MessagePersistedSource::Background),
                persist_assistant_with_media(
                    &sessions,
                    tmp.path(),
                    &session_id,
                    "✅ fm_tts delivered.".to_owned(),
                    media.clone(),
                    thread_id.to_owned(),
                    "fm_tts",
                ),
            )
            .await;

        let persisted = persisted.expect("background result row should persist");
        assert_eq!(persisted.committed_seq, 0);

        let handle = octos_bus::SessionHandle::open(tmp.path(), &session_id);
        let history = handle.session().messages.clone();
        assert_eq!(history.len(), 1, "one background completion row");
        let row = &history[0];
        assert_eq!(row.role, MessageRole::Assistant);
        assert_eq!(row.content, "✅ fm_tts delivered.");
        assert_eq!(row.media, media);
        assert_eq!(row.thread_id.as_deref(), Some(thread_id));
    }

    /// Fleet-UX soak NEW-03 (mini3 / mini5, 2026-05-23): the #1183 fix
    /// suppressed the synthesised "Background work started for `<tool>`."
    /// ack on the LIVE `message/persisted` broadcast for dual-negotiated
    /// clients by tagging the wire envelope `source: background`, but
    /// the JSONL row was still committed with `role: assistant`. The
    /// page handler at `handle_session_messages_page` walks JSONL
    /// directly with NO source filter, so any SPA refresh / replay
    /// re-rendered the suppressed bubble — soak captured 33 occurrences
    /// of the ack text in messages_page payloads under one turn.
    ///
    /// Post-fix the API persist site SKIPS the ack persist entirely
    /// when `ConversationResponse.synthesized_from_spawn_only` is true.
    /// The preamble (carrying `tool_calls` + preamble text) still
    /// persists as a normal assistant row. The background task's real
    /// outcome still flows via `BackgroundResultSender` (its own
    /// persist + `turn/spawn_complete` envelope), so the legitimate
    /// "task finished" signal is unaffected.
    ///
    /// This test simulates the full production persist sequence and
    /// asserts both invariants:
    ///   1. JSONL contains exactly ONE row (the preamble) — the ack
    ///      row is absent, so messages_page replay can NEVER ghost it.
    ///   2. Exactly ONE `message/persisted` envelope fires (the
    ///      preamble with `source: assistant`) — no Background
    ///      envelope appears because the persist that would have
    ///      triggered the observer never happens.
    #[tokio::test(flavor = "current_thread")]
    async fn synth_ack_not_persisted_to_jsonl_when_spawn_only() {
        use octos_core::ui_protocol::MessagePersistedSource;

        let _guard = message_commit_observer_test_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());

        // Wire a fresh ledger + observer the same way the live server
        // wires them on first `event_ledger` call.
        let ledger = Arc::new(UiProtocolLedger::new(64));
        install_message_commit_observer(ledger.clone());

        let session_id = SessionKey("local:spawn-only-synth-ack-no-persist".into());
        let mut subscriber = ledger.subscribe(&session_id);

        let tmp = tempfile::tempdir().expect("tempdir");
        let mut manager =
            octos_bus::SessionManager::open(tmp.path()).expect("session manager open");

        // Step 1: persist the iter-1 LLM reply (preamble + tool_calls)
        // exactly as the production persist loop at ui_protocol.rs
        // does — this is the `response.messages` walk, which always
        // commits regardless of `synthesized_from_spawn_only`.
        let preamble_text = "Sure, I'll kick off the pipeline now.".to_string();
        let preamble = Message {
            role: MessageRole::Assistant,
            content: preamble_text.clone(),
            media: vec![],
            tool_calls: Some(vec![octos_core::ToolCall {
                id: "tc-run_pipeline-1".into(),
                name: "run_pipeline".into(),
                arguments: serde_json::json!({}),
                metadata: None,
            }]),
            tool_call_id: None,
            reasoning_content: None,
            client_message_id: None,
            thread_id: Some("thread-spawn-only-synth-no-persist".into()),
            timestamp: Utc::now(),
        };
        manager
            .add_message_with_seq(&session_id, preamble)
            .await
            .expect("commit preamble assistant row");

        // Step 2: simulate the production persist site's branch for
        // the synthesised ack. The new code path at
        // `ui_protocol.rs`'s `if skip_synthesized_spawn_only_ack`
        // gates: when `response.synthesized_from_spawn_only` is true,
        // skip the `add_message_with_seq` call entirely. We mirror
        // that here: a `final_assistant` Message exists in scope (the
        // synthesised ack) but we DO NOT persist it.
        let _ack_that_must_not_persist = Message {
            role: MessageRole::Assistant,
            content: "Background work started for `run_pipeline`. \
                 The final result will be delivered automatically when it is ready."
                .to_string(),
            media: vec![],
            tool_calls: None,
            tool_call_id: None,
            reasoning_content: None,
            client_message_id: None,
            thread_id: Some("thread-spawn-only-synth-no-persist".into()),
            timestamp: Utc::now(),
        };
        // Intentionally no `manager.add_message_with_seq(...)` call.
        // This is the post-fix shape — the ack never reaches JSONL.

        // Invariant 1: JSONL contains exactly ONE row (the preamble).
        // The ack is absent — so `session/messages_page` walking
        // history can never resurface a ghost ack bubble on refresh.
        let session = manager.get_or_create(&session_id).await;
        let history = session.get_history(usize::MAX);
        assert_eq!(
            history.len(),
            1,
            "JSONL must contain ONLY the preamble row after the persist site \
             skips the synthesised ack; pre-fix the ack was persisted too \
             (the NEW-03 ghost ack bug). Got {} rows.",
            history.len(),
        );
        assert_eq!(
            history[0].content, preamble_text,
            "the surviving row must be the preamble (the iter-1 LLM reply with tool_calls)",
        );
        assert!(
            !history[0].content.starts_with("Background work started"),
            "no row may carry the synthesised ack text — that was the ghost-ack signature",
        );

        // Invariant 2: exactly ONE `message/persisted` envelope fires
        // (the preamble with `source: assistant`). The ack persist is
        // skipped, so the `MessageCommitObserver` never fires for it
        // — no Background envelope is emitted either.
        let mut assistant_envelopes: Vec<MessagePersistedEvent> = Vec::new();
        while let Ok(event) = subscriber.try_recv() {
            if let UiProtocolLedgerEvent::Notification(UiNotification::MessagePersisted(ev)) =
                &event.event
            {
                if ev.role == octos_core::MessageRole::Assistant.as_str() {
                    assistant_envelopes.push(ev.clone());
                }
            }
        }
        assert_eq!(
            assistant_envelopes.len(),
            1,
            "exactly ONE `message/persisted` envelope must fire (the preamble); \
             pre-fix TWO fired (preamble Assistant + ack Background); got {}",
            assistant_envelopes.len(),
        );
        assert_eq!(
            assistant_envelopes[0].source,
            MessagePersistedSource::Assistant,
            "the surviving envelope must be the preamble with source=Assistant",
        );
        assert!(
            !assistant_envelopes
                .iter()
                .any(|env| matches!(env.source, MessagePersistedSource::Background)),
            "NO Background envelope may fire — the ack persist is skipped \
             entirely so the observer never fabricates a Background source row",
        );

        // Restore the global observer slot to None so subsequent tests
        // see a clean state.
        octos_bus::set_message_commit_observer(None);
    }

    /// Fleet-UX soak round-2 NEW-03 follow-up (2026-05-23): a unit
    /// test pinning the persist-site gate's name-agnostic shape.
    ///
    /// The gate at the JSONL persist site
    /// (`run_standalone_turn` -> `should_skip_synthesized_spawn_only_ack_persist`)
    /// MUST key solely on the `synthesized_from_spawn_only` flag and
    /// the in-scope final-assistant carrier, NEVER on a hard-coded
    /// tool name. The agent loop
    /// (`agent/loop_runner.rs::process_message_inner`) sets that
    /// flag whenever the CURRENT iteration contains any tool call
    /// where `tools.is_spawn_only(tc.name)` returns true — so
    /// EVERY plugin/manifest-declared spawn_only tool plus the
    /// builtin `run_pipeline` (registered with `mark_spawn_only` in
    /// `runtime/profile.rs`) flows through the same skip path.
    ///
    /// Codex P2 (round-2 review) on PR #1193 caught the first
    /// iteration of this test "asserting by construction" — the test
    /// manually omitted the persist call so the assertions passed for
    /// every tool name regardless of the real gate. This rewrite
    /// drives the assertion through the actual production helper
    /// `should_skip_synthesized_spawn_only_ack_persist` so a future
    /// regression that narrowed the skip path to a hard-coded tool
    /// name (e.g. `if tc.name == "podcast_generate" { skip }`) WOULD
    /// flip this test red.
    #[test]
    fn synth_ack_not_persisted_for_run_pipeline_or_podcast_voices() {
        // Cover every spawn_only tool name observed in the round-2
        // soak (`e2e/test-results-fleet-ux-soak/mini{1,3,5}/iter-1/`)
        // plus a couple of names that ARE marked spawn_only in the
        // production registry (`mofa_slides`, `bg_research`) and a
        // synthetic generic name. A tool-name-specific regression
        // would only let one of these through.
        let tool_names = [
            "run_pipeline",
            "podcast_voices",
            "podcast_generate",
            "mofa_slides",
            "bg_research",
            "arbitrary_spawn_only_name_42",
        ];

        for tool_name in tool_names {
            // The production gate has only two inputs — both
            // tool-name-agnostic. We assert each input combination
            // collapses to the expected skip decision for EVERY
            // `tool_name` value, proving the gate cannot see the
            // tool name.
            assert!(
                should_skip_synthesized_spawn_only_ack_persist(true, true),
                "tool `{tool_name}`: skip MUST fire when \
                 `synthesized_from_spawn_only=true` AND the final-assistant \
                 carrier is in scope — this is the post-#1190 NEW-03 invariant. \
                 A regression that narrowed the skip to a hard-coded tool name \
                 would fail here for every name except the hard-coded one.",
            );
            assert!(
                !should_skip_synthesized_spawn_only_ack_persist(false, true),
                "tool `{tool_name}`: skip MUST NOT fire when \
                 `synthesized_from_spawn_only=false`, regardless of the carrier \
                 (normal LLM reply path).",
            );
            assert!(
                !should_skip_synthesized_spawn_only_ack_persist(true, false),
                "tool `{tool_name}`: skip MUST NOT fire when there is no \
                 final-assistant carrier in scope (defensive — the surrounding \
                 persist block short-circuits anyway, but the gate must too).",
            );
            assert!(
                !should_skip_synthesized_spawn_only_ack_persist(false, false),
                "tool `{tool_name}`: skip MUST NOT fire when both inputs are \
                 false (normal EndTurn with no carrier).",
            );
        }
    }

    /// Fleet-UX soak round-2 NEW-03 follow-up (2026-05-23): integration
    /// test mirroring the persist-site flow for multiple spawn_only
    /// tool names. Complements the unit test on
    /// `should_skip_synthesized_spawn_only_ack_persist` by exercising
    /// the JSONL persistence layer and the `MessageCommitObserver`
    /// ledger envelope for each name.
    ///
    /// Per iteration:
    ///   1. JSONL contains exactly ONE row (the preamble) — the ack
    ///      row is absent so messages_page replay cannot ghost-render.
    ///   2. Exactly ONE `message/persisted` envelope fires (the
    ///      preamble with `source: Assistant`) — no Background
    ///      envelope appears because the persist that would have
    ///      triggered the observer never happens.
    #[tokio::test(flavor = "current_thread")]
    async fn synth_ack_skip_invariants_hold_for_each_spawn_only_tool_name() {
        use octos_core::ui_protocol::MessagePersistedSource;

        // Cover every spawn_only tool name observed in the round-2 soak
        // (mini1 / mini3 / mini5 evidence in
        // `e2e/test-results-fleet-ux-soak/`) plus a couple of names that
        // never appeared in the soak but ARE marked spawn_only in the
        // production registry (`mofa_slides`, `bg_research`). A
        // tool-name-specific regression would flip this test red on
        // every name except the hard-coded one.
        let tool_names = [
            "run_pipeline",
            "podcast_voices",
            "podcast_generate",
            "mofa_slides",
            "bg_research",
            "arbitrary_spawn_only_name_42",
        ];

        for tool_name in tool_names {
            let _guard = message_commit_observer_test_lock()
                .lock()
                .unwrap_or_else(|e| e.into_inner());

            // Fresh ledger + observer per iteration so envelope counts
            // don't leak between tool-name cases.
            let ledger = Arc::new(UiProtocolLedger::new(64));
            install_message_commit_observer(ledger.clone());

            let session_id =
                SessionKey(format!("local:spawn-only-synth-ack-no-persist-{tool_name}"));
            let mut subscriber = ledger.subscribe(&session_id);

            let tmp = tempfile::tempdir().expect("tempdir");
            let mut manager =
                octos_bus::SessionManager::open(tmp.path()).expect("session manager open");

            // Step 1: the iter-1 preamble assistant row WITH a
            // spawn_only tool call — this row is always persisted (the
            // skip only applies to the synthesised ack carrier).
            let preamble_text = format!("Calling `{tool_name}` now.");
            let preamble = Message {
                role: MessageRole::Assistant,
                content: preamble_text.clone(),
                media: vec![],
                tool_calls: Some(vec![octos_core::ToolCall {
                    id: format!("tc-{tool_name}-1"),
                    name: tool_name.to_string(),
                    arguments: serde_json::json!({}),
                    metadata: None,
                }]),
                tool_call_id: None,
                reasoning_content: None,
                client_message_id: None,
                thread_id: Some(format!("thread-{tool_name}")),
                timestamp: Utc::now(),
            };
            manager
                .add_message_with_seq(&session_id, preamble)
                .await
                .expect("commit preamble assistant row");

            // Step 2: build the synthesised ack carrier and decide
            // whether to persist by calling the SAME production gate
            // the persist site uses. This routes the test through the
            // actual decision logic — a regression that narrowed
            // `should_skip_synthesized_spawn_only_ack_persist` to a
            // hard-coded tool name (or removed the skip) would flip
            // the gate's return value here for non-hard-coded names,
            // the `if !skip` branch below would then commit the ack,
            // and Invariant A would fail with a clear signal naming
            // the offending tool.
            let ack = Message {
                role: MessageRole::Assistant,
                content: format!(
                    "Background work started for `{tool_name}`. \
                     The final result will be delivered automatically when it is ready."
                ),
                media: vec![],
                tool_calls: None,
                tool_call_id: None,
                reasoning_content: None,
                client_message_id: None,
                thread_id: Some(format!("thread-{tool_name}")),
                timestamp: Utc::now(),
            };
            // Production inputs at the persist site: the agent loop
            // sets `synthesized_from_spawn_only=true` whenever the
            // current iteration contains ANY spawn_only call (which
            // is the case for every `tool_name` above), and the
            // final-assistant carrier is built in scope by
            // `final_assistant_message(...)`.
            let synthesized_from_spawn_only = true;
            let final_assistant_in_scope = true;
            let skip = should_skip_synthesized_spawn_only_ack_persist(
                synthesized_from_spawn_only,
                final_assistant_in_scope,
            );
            if !skip {
                // If the gate did NOT skip, the persist site DOES
                // commit the ack — replicate that here so Invariant A
                // surfaces the regression with a clear name in the
                // failure message.
                manager
                    .add_message_with_seq(&session_id, ack)
                    .await
                    .expect("commit ack assistant row (regression path)");
            }

            // Invariant A: JSONL contains exactly ONE row (the
            // preamble). For ANY spawn_only tool name, the ack row is
            // absent — `session/messages_page` cannot resurface a ghost
            // ack bubble on refresh.
            let session = manager.get_or_create(&session_id).await;
            let history = session.get_history(usize::MAX);
            assert_eq!(
                history.len(),
                1,
                "JSONL must contain ONLY the preamble row for spawn_only tool \
                 `{tool_name}`; if a future regression narrowed the skip path to a \
                 tool-name match, names other than the hard-coded one would fail \
                 here. Got {} rows.",
                history.len(),
            );
            assert_eq!(
                history[0].content, preamble_text,
                "the surviving row must be the preamble (not the ack) for `{tool_name}`",
            );
            assert!(
                !history[0].content.starts_with("Background work started"),
                "no row may carry the synthesised ack text for `{tool_name}` — \
                 that was the round-1 ghost-ack signature",
            );

            // Invariant B: exactly ONE `message/persisted` envelope
            // fires (the preamble with `source: assistant`) — regardless
            // of `<tool_name>`. The ack persist is skipped, so the
            // `MessageCommitObserver` never fires for it.
            let mut assistant_envelopes: Vec<MessagePersistedEvent> = Vec::new();
            while let Ok(event) = subscriber.try_recv() {
                if let UiProtocolLedgerEvent::Notification(UiNotification::MessagePersisted(ev)) =
                    &event.event
                {
                    if ev.role == octos_core::MessageRole::Assistant.as_str() {
                        assistant_envelopes.push(ev.clone());
                    }
                }
            }
            assert_eq!(
                assistant_envelopes.len(),
                1,
                "exactly ONE `message/persisted` envelope must fire for spawn_only \
                 tool `{tool_name}`; got {}",
                assistant_envelopes.len(),
            );
            assert_eq!(
                assistant_envelopes[0].source,
                MessagePersistedSource::Assistant,
                "the surviving envelope for `{tool_name}` must be the preamble \
                 with source=Assistant",
            );
            assert!(
                !assistant_envelopes
                    .iter()
                    .any(|env| matches!(env.source, MessagePersistedSource::Background)),
                "NO Background envelope may fire for `{tool_name}` — the ack \
                 persist is skipped entirely",
            );

            // Restore the global observer slot between iterations.
            octos_bus::set_message_commit_observer(None);
            drop(_guard);
        }
    }

    /// Codex P2 follow-up on the NEW-03 fix: a self-paced (or
    /// `maintenance`) loop that fires a bare spawn_only call with NO
    /// LLM preamble has only the synthesised ack as its turn-final
    /// assistant content. Pre-codex-P2 the new skip-persist path
    /// dropped both the JSONL row AND the `final_send` signal — so
    /// `apply_self_paced_response` never fired, `next_run_at_ms`
    /// stayed cleared from the fire-time stamp, and the loop stalled.
    ///
    /// Post-codex-P2 the skip path flips `final_assistant_persisted`
    /// to true, which routes the captured reply through to the
    /// post-turn block. This test pins the orchestrator-level invariant
    /// the fix relies on: feeding `apply_self_paced_response` the
    /// synthesised ack text (which has no `<<loop-next-in: ...>>`
    /// hint) MUST stamp a fresh `next_run_at_ms` ~= now +
    /// `SELF_PACED_DEFAULT_DELAY_SECONDS` (15 min default), so the
    /// loop keeps scheduling.
    /// Codex round-3 P2 acceptance: when a spawn_only self-paced
    /// turn has a preamble carrying a `<<loop-next-in: 60s>>` hint,
    /// the captured_final_reply must end up as the PREAMBLE text
    /// (not the synthesised ack) so `apply_self_paced_response`
    /// parses the model-requested 60s delay — NOT the 15-min
    /// default — and stamps `next_run_at_ms` accordingly.
    ///
    /// This pins the integration shape: feed the preamble text
    /// (which `captured_final_reply_for_synth_ack_skip` returns
    /// when a preamble is persisted) through
    /// `apply_self_paced_response` and assert the parsed delay is
    /// the hint, not the fallback.
    #[test]
    fn self_paced_loop_honours_preamble_hint_when_spawn_only_skipped() {
        use crate::api::agent_orchestrator::{
            InProcessAgentOrchestrator, LoopCreateRequest, LoopListRequest,
        };

        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id =
            SessionKey::with_profile("tenant-round3", "api", "self-paced-preamble-hint");
        let created = orchestrator
            .create_loop(LoopCreateRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-round3".into(),
                prompt: Some("watch the build".into()),
                command: None,
                interval_seconds: None,
                mode: Some("self_paced".into()),
            })
            .expect("create self-paced loop");
        let loop_id = created["loop_id"].as_str().expect("loop id").to_owned();

        // Wire shape: a preamble with hint AND a synth ack present.
        // The helper picks the preamble.
        let preamble = "Starting the pipeline. <<loop-next-in: 60s>>";
        let synth_ack = "Background work started for `run_pipeline`. \
                         The final result will be delivered automatically when it is ready."
            .to_string();
        let captured = captured_final_reply_for_synth_ack_skip(synth_ack, Some(preamble));
        assert_eq!(
            captured, preamble,
            "helper must pick the preamble text when present",
        );

        let before = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        let parsed = orchestrator
            .apply_self_paced_response(&loop_id, "tenant-round3", &captured)
            .expect("apply_self_paced_response on preamble");
        assert_eq!(
            parsed,
            Some(std::time::Duration::from_secs(60)),
            "preamble carried `<<loop-next-in: 60s>>` — parser MUST return 60s, NOT the 15-min default",
        );

        // Verify next_run_at_ms is ~60s ahead (NOT 900s) — the
        // model-requested delay deterministically beats the
        // history-fallback race.
        let listed = orchestrator
            .list_loops(LoopListRequest {
                session_id: Some(session_id.clone()),
                profile_id: "tenant-round3".into(),
            })
            .expect("list_loops");
        let loops = listed
            .get("loops")
            .and_then(|v| v.as_array())
            .expect("loops array");
        let record = loops
            .iter()
            .find(|loop_val| loop_val.get("loop_id").and_then(|v| v.as_str()) == Some(&loop_id))
            .expect("loop record present");
        let next = record
            .get("next_run_at_ms")
            .and_then(|v| v.as_i64())
            .expect("self-paced loop must have a fresh next_run_at_ms");
        let delta_ms = next - before;
        assert!(
            (50_000..=70_000).contains(&delta_ms),
            "next_run_at_ms must be ~60s in the future (got {delta_ms} ms) — proves the preamble's \
             `<<loop-next-in: 60s>>` hint beat the default 15-min fallback",
        );
    }

    #[test]
    fn self_paced_loop_reschedules_when_only_assistant_content_is_synth_ack() {
        use crate::api::agent_orchestrator::{
            InProcessAgentOrchestrator, LoopCreateRequest, LoopListRequest,
        };

        // Codex round-2 P3: use a private orchestrator (NOT the
        // process-wide `default_agent_orchestrator` singleton) so
        // this test can't race with another module test that calls
        // `clear_autonomy_runtime_state_for_test` or otherwise
        // mutates the global state between our `create_loop` and
        // `list_loops`.
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id =
            SessionKey::with_profile("tenant-new03", "api", "self-paced-bare-spawn-only");
        let created = orchestrator
            .create_loop(LoopCreateRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-new03".into(),
                prompt: Some("kick off the pipeline".into()),
                command: None,
                interval_seconds: None,
                mode: Some("self_paced".into()),
            })
            .expect("create self-paced loop");
        let loop_id = created["loop_id"].as_str().expect("loop id").to_owned();

        // Simulate the synthesised spawn_only ack text exactly as
        // `loop_runner::process_message_inner` fabricates it — note
        // no `<<loop-next-in: ...>>` hint.
        let ack_text = "Background work started for `run_pipeline`. \
             The final result will be delivered automatically when it is ready.";

        let before = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        let parsed = orchestrator
            .apply_self_paced_response(&loop_id, "tenant-new03", ack_text)
            .expect("apply_self_paced_response on synthesised ack");
        assert_eq!(
            parsed, None,
            "ack carries no `<<loop-next-in: ...>>` hint, so the parser must return None",
        );

        // The default fallback delay is 15 minutes (900 s). Assert the
        // next_run_at_ms lands inside a tolerant window around that.
        // Use the public `list_loops` API to inspect the stamped value
        // (the internal `state()` accessor is private).
        let listed = orchestrator
            .list_loops(LoopListRequest {
                session_id: Some(session_id.clone()),
                profile_id: "tenant-new03".into(),
            })
            .expect("list_loops");
        let loops = listed
            .get("loops")
            .and_then(|v| v.as_array())
            .expect("loops array");
        let record = loops
            .iter()
            .find(|loop_val| loop_val.get("loop_id").and_then(|v| v.as_str()) == Some(&loop_id))
            .expect("created loop record present");
        let next = record
            .get("next_run_at_ms")
            .and_then(|v| v.as_i64())
            .expect(
                "self-paced loop MUST have a fresh next_run_at_ms after firing — \
                 if this is null the loop has stalled (the NEW-03 codex P2 regression)",
            );
        let delta_ms = next - before;
        assert!(
            (890_000..=910_000).contains(&delta_ms),
            "next_run_at_ms must be roughly 900s (SELF_PACED_DEFAULT_DELAY_SECONDS) in the \
             future (got {delta_ms} ms) — confirms `apply_self_paced_response` fell back to \
             the default delay when the ack carried no hint",
        );
    }

    /// Codex P2 follow-up: the `turn/spawn_complete` envelope's flat
    /// `seq` field carries the COMMITTED-ROW seq (the index in the
    /// session message log, identical to `MessagePersistedEvent.seq`)
    /// — NOT the UI-ledger cursor seq. The two scales differ in any
    /// turn that has prior ledger notifications, so upgraded clients
    /// reusing their `MessagePersisted` reducer for spawn completions
    /// MUST observe the persisted-row seq the producer wrote, not the
    /// ledger-assigned cursor seq.
    #[tokio::test]
    async fn ledger_preserves_producer_seq_and_stamps_only_cursor() {
        let ledger = UiProtocolLedger::new(8);
        let session_id = SessionKey("local:seq".into());

        // Producer sets `seq = 7` (the committed-row index from the
        // persist path). Ledger appends and stamps cursor.seq, but
        // must leave `seq` untouched.
        let mut event = match turn_spawn_complete_for(&session_id) {
            UiNotification::TurnSpawnComplete(ev) => ev,
            _ => unreachable!("test fixture is turn/spawn_complete"),
        };
        event.seq = 7;
        event.cursor.seq = 0; // producer seeds 0; ledger stamps the real cursor.
        let appended = ledger.append_notification(UiNotification::TurnSpawnComplete(event));

        let stamped = match &appended.event {
            UiProtocolLedgerEvent::Notification(UiNotification::TurnSpawnComplete(ev)) => ev,
            _ => panic!("expected turn/spawn_complete back from the ledger"),
        };
        assert_eq!(
            stamped.seq, 7,
            "ledger must NOT overwrite the producer's committed-row seq",
        );
        assert!(
            stamped.cursor.seq > 0,
            "cursor.seq must be the ledger-assigned non-zero cursor",
        );

        // Cursor is strictly monotonic across appends (same contract
        // as the existing MessagePersisted path); flat `seq` is
        // independent and tracked by the producer.
        let mut event2 = match turn_spawn_complete_for(&session_id) {
            UiNotification::TurnSpawnComplete(ev) => ev,
            _ => unreachable!(),
        };
        event2.seq = 8;
        let appended2 = ledger.append_notification(UiNotification::TurnSpawnComplete(event2));
        let stamped2 = match &appended2.event {
            UiProtocolLedgerEvent::Notification(UiNotification::TurnSpawnComplete(ev)) => ev,
            _ => panic!("turn/spawn_complete"),
        };
        assert!(stamped2.cursor.seq > stamped.cursor.seq);
        assert_eq!(stamped2.seq, 8);
    }

    /// End-to-end through the live forwarder for an OLD client (did NOT
    /// negotiate `event.spawn_complete.v1`): they see `message/persisted`
    /// (Background source preserved) and do NOT see `turn/spawn_complete`.
    /// This is the back-compat path that keeps existing TUI/CLI consumers
    /// working unchanged.
    #[tokio::test]
    async fn live_forwarder_falls_back_to_message_persisted_for_old_client() {
        let (ws, mut rx) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:oldfeat".into());
        let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        let live_rx = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws.connection_id(),
            // Old client: has message_persisted but NOT spawn_complete.
            features_for_spawn_complete_test(true, false),
            None,
            live_rx,
            forwarders.clone(),
        )
        .await;

        ledger.append_notification(background_message_persisted_for(&session_id));
        ledger.append_notification(turn_spawn_complete_for(&session_id));

        let frame = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
            .await
            .expect("expected the legacy message/persisted within 1s")
            .expect("ws still open");
        assert_eq!(
            frame_method(&frame).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED),
            "first frame must be the legacy message/persisted shape for old clients",
        );

        // The new envelope must NOT be delivered to an un-negotiated client.
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        assert!(
            rx.try_recv().is_err(),
            "no second frame: turn/spawn_complete is suppressed for old clients",
        );

        abort_live_forwarders(&forwarders, &ledger).await;
    }

    #[tokio::test]
    async fn live_forwarder_fans_out_to_two_concurrent_ws_connections() {
        let (ws_a, mut rx_a) = ws_connection_for_test(16);
        let (ws_b, mut rx_b) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:fanout".into());
        let forwarders_a: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let forwarders_b: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        let rx_a_live = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws_a.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws_a.connection_id(),
            features_with_message_persisted(true),
            None,
            rx_a_live,
            forwarders_a.clone(),
        )
        .await;
        let rx_b_live = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws_b.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws_b.connection_id(),
            features_with_message_persisted(true),
            None,
            rx_b_live,
            forwarders_b.clone(),
        )
        .await;

        ledger.append_notification(message_persisted_for(&session_id));

        let frame_a = tokio::time::timeout(std::time::Duration::from_secs(1), rx_a.recv())
            .await
            .expect("ws_a frame")
            .expect("ws_a open");
        let frame_b = tokio::time::timeout(std::time::Duration::from_secs(1), rx_b.recv())
            .await
            .expect("ws_b frame")
            .expect("ws_b open");
        assert_eq!(
            frame_method(&frame_a).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );
        assert_eq!(
            frame_method(&frame_b).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );

        // Disconnect ws_a; ws_b must continue receiving subsequent events.
        abort_live_forwarders(&forwarders_a, &ledger).await;
        drop(rx_a);
        ledger.append_notification(message_persisted_for(&session_id));
        let frame_b2 = tokio::time::timeout(std::time::Duration::from_secs(1), rx_b.recv())
            .await
            .expect("ws_b frame after sibling drop")
            .expect("ws_b still open");
        assert_eq!(
            frame_method(&frame_b2).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );

        abort_live_forwarders(&forwarders_b, &ledger).await;
    }

    // -- Codex PR #761 review fixes ----------------------------------------

    /// MUST-FIX-1: an event appended *after* the replay snapshot but
    /// *before* the live forwarder is wired up (the gap between
    /// `replay_after_with_head` returning and `spawn_live_forwarder`
    /// being awaited) must still reach the WS via the broadcast. The
    /// baseline must come from the replay snapshot's head — not the
    /// later session/open seq — otherwise a session/open append at H+2
    /// would shift the baseline up and silently drop the H+1 event.
    #[tokio::test]
    async fn live_forwarder_emits_event_appended_between_replay_and_forwarder_install() {
        let (ws, mut rx) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:gap".into());
        let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        // Pre-existing event at seq=1 — would be in replay history.
        let initial = ledger.append_notification(message_persisted_for(&session_id));
        assert_eq!(initial.cursor.seq, 1);

        // Snapshot replay (head=1) + subscribe in the same order
        // handle_session_open does.
        let live_rx = ledger.subscribe(&session_id);
        let (_replay, replay_head) = ledger
            .replay_after_with_head(
                &session_id,
                Some(&UiCursor {
                    stream: session_id.0.clone(),
                    seq: 0,
                }),
            )
            .expect("replay snapshot");
        assert_eq!(replay_head, 1);

        // GAP event — landed AFTER replay snapshot was taken but BEFORE
        // the forwarder is installed. With the broken design this would
        // be filtered out (baseline shifted to session/open's seq=H+2);
        // with the fix the broadcast buffer holds it and the forwarder
        // emits it once installed.
        let gap = ledger.append_notification(message_persisted_for(&session_id));
        assert_eq!(gap.cursor.seq, 2);

        // Append session/open AFTER the gap event — exactly the
        // ordering open_session_result produces.
        let opened = ledger.append_notification_from(
            UiNotification::SessionOpened(SessionOpened {
                session_id: session_id.clone(),
                active_profile_id: Some(MAIN_PROFILE_ID.to_owned()),
                workspace_root: None,
                context: None,
                context_state: None,
                cursor: None,
                panes: None,
                capabilities: UiProtocolCapabilities::first_server_slice(),
                reasoning_effort: None,
            }),
            ws.connection_id(),
        );
        assert_eq!(opened.cursor.seq, 3);

        // Wire up the forwarder using replay_head as the baseline. The
        // gap event has seq > baseline AND it is not from this
        // connection, so it must surface on the WS.
        spawn_live_forwarder(
            ws.clone(),
            ledger.clone(),
            session_id.clone(),
            replay_head,
            ws.connection_id(),
            features_with_message_persisted(true),
            None,
            live_rx,
            forwarders.clone(),
        )
        .await;

        let frame = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
            .await
            .expect("forwarder must emit gap event")
            .expect("ws still open");
        assert_eq!(
            frame_method(&frame).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED),
            "the H+1 gap event must reach the WS, not be silently filtered"
        );

        // The session/open event itself must NOT come back via the
        // broadcast (it carries our connection_id, so the forwarder
        // skips it — the handler already direct-sent it inline).
        assert!(
            rx.try_recv().is_err(),
            "no further frames expected: session/open must be self-suppressed"
        );

        abort_live_forwarders(&forwarders, &ledger).await;
    }

    /// MUST-FIX-2: a `send_notification_durable` call from the same
    /// connection that owns an active live forwarder must deliver the
    /// frame exactly once. Without `from_connection` self-suppression
    /// the forwarder would receive the broadcast and double-send.
    #[tokio::test]
    async fn send_notification_durable_does_not_double_deliver_via_live_forwarder() {
        let (ws, mut rx) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:dedup".into());
        let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        let live_rx = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws.connection_id(),
            features_with_message_persisted(true),
            None,
            live_rx,
            forwarders.clone(),
        )
        .await;

        // Direct-send via the standard handler path. This both persists
        // (with our connection_id stamped) and direct-sends inline.
        send_notification_durable(&ws, &ledger, message_persisted_for(&session_id))
            .expect("direct send succeeds");

        // Exactly one frame must arrive.
        let first = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
            .await
            .expect("first frame")
            .expect("ws open");
        assert_eq!(
            frame_method(&first).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );
        // Give the forwarder time to (incorrectly) re-emit if the fix
        // regresses; with self-suppression nothing further must arrive.
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        assert!(
            rx.try_recv().is_err(),
            "send_notification_durable must deliver exactly once on its own connection"
        );

        // Sanity: a different connection's forwarder still receives the
        // event via fan-out (the suppression is per-connection).
        let (ws_other, mut rx_other) = ws_connection_for_test(16);
        let forwarders_other: SharedLiveForwarders =
            Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let live_rx_other = ledger.subscribe(&session_id);
        spawn_live_forwarder(
            ws_other.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws_other.connection_id(),
            features_with_message_persisted(true),
            None,
            live_rx_other,
            forwarders_other.clone(),
        )
        .await;
        send_notification_durable(&ws, &ledger, message_persisted_for(&session_id))
            .expect("second send");
        let frame_other = tokio::time::timeout(std::time::Duration::from_secs(1), rx_other.recv())
            .await
            .expect("other connection sees fan-out")
            .expect("ws_other open");
        assert_eq!(
            frame_method(&frame_other).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );

        abort_live_forwarders(&forwarders, &ledger).await;
        abort_live_forwarders(&forwarders_other, &ledger).await;
    }

    /// Stuck-chip fix (specialist lane): a TERMINAL `agent/updated` emitted
    /// through the supervisor sink must be appended to the durable per-session
    /// ledger (so reconnect replay observes the flip), while non-terminal
    /// updates stay ephemeral (never ledgered — they'd bloat replay history).
    #[tokio::test]
    async fn supervisor_sink_ledgers_terminal_agent_updates_only() {
        let (ws, mut rx) = ws_connection_for_test(16);
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:sink-durable".into());
        let sink = WsSupervisorEventSink {
            ws: ws.clone(),
            ledger: ledger.clone(),
        };

        let agent_json = |status: &str| {
            json!({
                "session_id": session_id.0,
                "agent": {
                    "agent_id": "edison",
                    "session_id": session_id.0,
                    "path": "master/edison",
                    "role": "worker",
                    "nickname": "Edison",
                    "backend_kind": "cli_process",
                    "status": status,
                    "profile_id": "dev",
                    "created_at_ms": 1,
                    "updated_at_ms": 1,
                }
            })
        };

        // Non-terminal: delivered live, but must NOT be appended durably.
        sink.emit_supervisor_event(
            octos_core::ui_protocol::methods::AGENT_UPDATED,
            agent_json("running"),
        );
        // Terminal: must be appended to the durable ledger.
        sink.emit_supervisor_event(
            octos_core::ui_protocol::methods::AGENT_UPDATED,
            agent_json("failed"),
        );

        // Both frames still reach the live connection exactly once each.
        for expected_status in ["running", "failed"] {
            let frame = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
                .await
                .expect("live frame")
                .expect("ws open");
            assert_eq!(
                frame_method(&frame).as_deref(),
                Some(octos_core::ui_protocol::methods::AGENT_UPDATED),
                "live delivery must be preserved for {expected_status}"
            );
        }

        let (events, _) = ledger
            .snapshot_with_cursor(&session_id, None)
            .expect("ledger snapshot");
        let ledgered_statuses: Vec<&str> = events
            .iter()
            .filter_map(|event| match &event.event {
                UiProtocolLedgerEvent::Notification(UiNotification::AgentUpdated(update)) => {
                    Some(update.agent.status.as_str())
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            ledgered_statuses,
            vec!["failed"],
            "exactly the terminal update must be ledgered — non-terminal stays ephemeral"
        );
    }

    /// MUST-FIX-3: a `subscribe()` call followed by dropping the
    /// receiver (modelling a failed `session/open` path) must not leak
    /// a sender. The `prune_subscriber_if_idle` hook called on the
    /// failure path reclaims the slot immediately.
    #[tokio::test]
    async fn session_open_failure_path_does_not_leak_broadcast_sender() {
        let ledger = Arc::new(UiProtocolLedger::new(16));
        let session_id = SessionKey("local:leakcheck".into());

        // Mirror handle_session_open's "subscribe BEFORE
        // open_session_result" ordering. Then simulate failure: drop
        // the receiver, prune.
        let live_rx = ledger.subscribe(&session_id);
        assert_eq!(ledger.subscriber_count(), 1, "sender installed");

        drop(live_rx);
        let pruned = ledger.prune_subscriber_if_idle(&session_id);
        assert!(pruned, "failed open must reclaim the orphan sender");
        assert_eq!(
            ledger.subscriber_count(),
            0,
            "no senders survive a failed session/open"
        );

        // Steady-state sweep also reclaims any orphans that escape the
        // failure path (defence in depth).
        let kept = ledger.subscribe(&session_id);
        ledger.prune_idle_subscribers(); // receiver still alive — no-op.
        assert_eq!(ledger.subscriber_count(), 1);
        drop(kept);
        assert_eq!(
            ledger.prune_idle_subscribers(),
            1,
            "sweep reclaims orphans after every receiver drops"
        );
        assert_eq!(ledger.subscriber_count(), 0);
    }

    /// Lag handling: when the broadcast buffer overflows, the receiver
    /// observes `RecvError::Lagged(n)` and the forwarder must NOT die —
    /// it logs and keeps pumping subsequent events. The earlier missed
    /// events are recoverable via cursor replay (the ledger is durable).
    #[tokio::test]
    async fn live_forwarder_survives_broadcast_lag_and_keeps_pumping() {
        let (ws, mut rx) = ws_connection_for_test(WS_WRITER_CHANNEL_CAPACITY);
        let ledger = Arc::new(UiProtocolLedger::new(2048));
        let session_id = SessionKey("local:lag".into());
        let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));

        // Subscribe but don't pump yet. Overflow the broadcast capacity
        // (LIVE_BROADCAST_CAPACITY = 256) so the receiver lags.
        let live_rx = ledger.subscribe(&session_id);
        for _ in 0..512 {
            ledger.append_notification(message_persisted_for(&session_id));
        }

        // Now install the forwarder — its first recv() will see
        // Lagged(n). It must log and continue, not abort.
        spawn_live_forwarder(
            ws.clone(),
            ledger.clone(),
            session_id.clone(),
            0,
            ws.connection_id(),
            features_with_message_persisted(true),
            None,
            live_rx,
            forwarders.clone(),
        )
        .await;

        // A fresh append after lag must be delivered.
        ledger.append_notification(message_persisted_for(&session_id));
        let frame = tokio::time::timeout(std::time::Duration::from_secs(2), rx.recv())
            .await
            .expect("post-lag frame must arrive — forwarder kept pumping")
            .expect("ws still open");
        assert_eq!(
            frame_method(&frame).as_deref(),
            Some(octos_core::ui_protocol::methods::MESSAGE_PERSISTED)
        );

        abort_live_forwarders(&forwarders, &ledger).await;
    }

